insert into public.academy_kb_items (id, key, kind, deck, trades, state_code, difficulty, prompt, answer, options, correct, explanation, section_id, citation, basis, origin, status, exam_tags, sort_order) values
  (md5('academykb:item:fp-trigger-height')::uuid, 'fp-trigger-height', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'easy', 'Under federal OSHA construction rules, an employee on a walking/working surface with an unprotected side or edge must be protected from falling at what height above a lower level?', '6 feet or more', array['10 feet or more', '15 feet or more', '6 feet or more', '4 feet or more']::text[], 2, '29 CFR 1926.501(b)(1) sets 6 feet as the trigger height for unprotected sides and edges. Scaffolds and some other situations have their own rules.', md5('academykb:section:cfr:1926.501(b)')::uuid, '29 CFR 1926.501(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 0),
  (md5('academykb:item:fp-three-systems')::uuid, 'fp-three-systems', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'medium', 'Which three systems does OSHA list for protecting workers at unprotected sides and edges?', 'Guardrail systems, safety net systems, or personal fall arrest systems', array['Warning lines, hard hats, or toeboards', 'Body belts, ropes, or anchors', 'Ladders, scaffolds, or aerial lifts', 'Guardrail systems, safety net systems, or personal fall arrest systems']::text[], 3, 'These are the conventional fall protection systems named in 1926.501(b)(1).', md5('academykb:section:cfr:1926.501(b)')::uuid, '29 CFR 1926.501(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 1),
  (md5('academykb:item:fp-surface-strength')::uuid, 'fp-surface-strength', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'medium', 'Before employees work on a walking/working surface, what must the employer determine?', 'That the surface has the strength and structural integrity to support employees safely', array['That the surface is less than 6 feet above grade', 'That the owner has signed a waiver', 'That the surface has been painted with anti-slip coating', 'That the surface has the strength and structural integrity to support employees safely']::text[], 3, '1926.501(a)(2) puts this duty on the employer, and employees may work there only when the surface is strong enough.', md5('academykb:section:cfr:1926.501(a)')::uuid, '29 CFR 1926.501(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 2),
  (md5('academykb:item:fp-falling-objects')::uuid, 'fp-falling-objects', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'medium', 'When an employee is exposed to falling objects, what must the employer have each employee wear, in addition to using toeboards, a canopy or a barricaded area?', 'A hard hat', array['A full-body harness', 'Hearing protection', 'A high-visibility vest', 'A hard hat']::text[], 3, '1926.501(c) requires hard hats plus one of three measures: toeboards/screens/guardrails, a canopy, or a barricaded area.', md5('academykb:section:cfr:1926.501(c)')::uuid, '29 CFR 1926.501(c)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 3),
  (md5('academykb:item:fp-guardrail-height')::uuid, 'fp-guardrail-height', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'easy', 'What is the required top edge height of a guardrail top rail under OSHA''s construction rules?', '42 inches, plus or minus 3 inches', array['42 inches, plus or minus 3 inches', '30 inches minimum', '48 inches minimum', '36 inches, plus or minus 2 inches']::text[], 0, '1926.502(b)(1): 42 inches ±3 inches above the walking/working level. When employees use stilts, the height increases by the stilt height.', md5('academykb:section:cfr:1926.502(b)')::uuid, '29 CFR 1926.502(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 4),
  (md5('academykb:item:fp-guardrail-stilts')::uuid, 'fp-guardrail-stilts', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'hard', 'Workers on a guarded platform are using stilts. How does that change the guardrail top rail height?', 'It must be increased by an amount equal to the height of the stilts', array['It must be doubled', 'Stilts are prohibited on guarded platforms', 'No change is required', 'It must be increased by an amount equal to the height of the stilts']::text[], 3, null, md5('academykb:section:cfr:1926.502(b)')::uuid, '29 CFR 1926.502(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 5),
  (md5('academykb:item:fp-midrail')::uuid, 'fp-midrail', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'medium', 'Where must a guardrail midrail be installed when midrails are used?', 'Midway between the top edge of the guardrail and the walking/working level', array['12 inches above the walking surface', '6 inches below the top rail', 'Anywhere, as long as it is continuous', 'Midway between the top edge of the guardrail and the walking/working level']::text[], 3, null, md5('academykb:section:cfr:1926.502(b)')::uuid, '29 CFR 1926.502(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 6),
  (md5('academykb:item:fp-baluster-spacing')::uuid, 'fp-baluster-spacing', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'hard', 'In an OSHA guardrail system, intermediate members such as balusters between posts may be no more than how far apart?', '19 inches', array['19 inches', '24 inches', '12 inches', '4 inches']::text[], 0, 'This is the OSHA jobsite guardrail rule. Permanent guards on homes follow the building code, which is much stricter about openings.', md5('academykb:section:cfr:1926.502(b)')::uuid, '29 CFR 1926.502(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 7),
  (md5('academykb:item:fp-body-belts')::uuid, 'fp-body-belts', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'medium', 'Since January 1, 1998, which item is not acceptable as part of a personal fall arrest system?', 'A body belt', array['A full-body harness', 'A locking snaphook', 'A shock-absorbing lanyard', 'A body belt']::text[], 3, 'A body belt may still be used in a positioning device system, which is regulated separately.', md5('academykb:section:cfr:1926.502(d)')::uuid, '29 CFR 1926.502(d)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 8),
  (md5('academykb:item:fp-dring-strength')::uuid, 'fp-dring-strength', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'hard', 'What minimum tensile strength must D-rings and snaphooks in a personal fall arrest system have?', '5,000 pounds', array['3,600 pounds', '5,000 pounds', '10,000 pounds', '1,800 pounds']::text[], 1, 'They must also be proof-tested to 3,600 pounds without cracking, breaking or permanent deformation.', md5('academykb:section:cfr:1926.502(d)')::uuid, '29 CFR 1926.502(d)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 9),
  (md5('academykb:item:fp-locking-snaphooks')::uuid, 'fp-locking-snaphooks', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'medium', 'Since January 1, 1998, what type of snaphook must be used in personal fall arrest systems?', 'Locking type only', array['Any snaphook rated for 3,600 pounds', 'Carabiners only', 'Non-locking aluminum', 'Locking type only']::text[], 3, null, md5('academykb:section:cfr:1926.502(d)')::uuid, '29 CFR 1926.502(d)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 10),
  (md5('academykb:item:fp-plan-who')::uuid, 'fp-plan-who', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'medium', 'Who must prepare a fall protection plan used in place of conventional fall protection?', 'A qualified person', array['The building official', 'The property owner', 'Any employee on the crew', 'A qualified person']::text[], 3, 'The plan must be specific to the site, kept up to date, and any changes approved by a qualified person.', md5('academykb:section:cfr:1926.502(k)')::uuid, '29 CFR 1926.502(k)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 11),
  (md5('academykb:item:fp-plan-when')::uuid, 'fp-plan-when', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'hard', 'A written fall protection plan (instead of guardrails, nets or personal fall arrest) is an option only for which kinds of work, and only when conventional protection is infeasible or creates a greater hazard?', 'Leading edge work, precast concrete erection, or residential construction', array['Painting and finish work', 'Any work the owner approves', 'Any work under 15 feet', 'Leading edge work, precast concrete erection, or residential construction']::text[], 3, null, md5('academykb:section:cfr:1926.502(k)')::uuid, '29 CFR 1926.502(k)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 12),
  (md5('academykb:item:fp-plan-where')::uuid, 'fp-plan-where', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'medium', 'Where must a copy of the fall protection plan, with all approved changes, be kept?', 'At the job site', array['At the company office only', 'With the building department', 'Nowhere; a verbal plan is enough', 'At the job site']::text[], 3, null, md5('academykb:section:cfr:1926.502(k)')::uuid, '29 CFR 1926.502(k)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 13),
  (md5('academykb:item:fp-plan-supervision')::uuid, 'fp-plan-supervision', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'medium', 'Whose supervision must the implementation of a fall protection plan be under?', 'A competent person', array['A licensed engineer', 'The homeowner', 'An OSHA inspector', 'A competent person']::text[], 3, null, md5('academykb:section:cfr:1926.502(k)')::uuid, '29 CFR 1926.502(k)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 14),
  (md5('academykb:item:fp-training-who')::uuid, 'fp-training-who', 'question', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'medium', 'Fall protection training for employees exposed to fall hazards must be given by whom, as necessary?', 'A competent person qualified in the listed areas', array['Any coworker', 'OSHA staff', 'The equipment manufacturer only', 'A competent person qualified in the listed areas']::text[], 3, null, md5('academykb:section:cfr:1926.503')::uuid, '29 CFR 1926.503', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 15),
  (md5('academykb:item:fp-card-trigger')::uuid, 'fp-card-trigger', 'flashcard', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'medium', 'OSHA fall protection trigger height for unprotected sides and edges in construction', '6 feet above a lower level (29 CFR 1926.501(b)(1)). Protect with guardrails, safety nets or personal fall arrest.', null, null, null, md5('academykb:section:cfr:1926.501(b)')::uuid, '29 CFR 1926.501(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 16),
  (md5('academykb:item:fp-card-guardrail')::uuid, 'fp-card-guardrail', 'flashcard', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'medium', 'OSHA guardrail top rail height', '42 inches ±3 inches above the walking/working level; midrails halfway between (29 CFR 1926.502(b)).', null, null, null, md5('academykb:section:cfr:1926.502(b)')::uuid, '29 CFR 1926.502(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 17),
  (md5('academykb:item:fp-card-plan')::uuid, 'fp-card-plan', 'flashcard', 'osha-fall-protection', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'roofing', 'framing', 'siding', 'decks', 'windows-doors', 'pole-barns', 'garages']::text[], null, 'medium', 'Fall protection plan: three must-haves', 'Prepared by a qualified person, kept at the job site, and implemented under a competent person''s supervision (29 CFR 1926.502(k)).', null, null, null, md5('academykb:section:cfr:1926.502(k)')::uuid, '29 CFR 1926.502(k)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 18),
  (md5('academykb:item:sc-fall-height')::uuid, 'sc-fall-height', 'question', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'medium', 'Above what height must each employee on a scaffold be protected from falling to a lower level?', 'More than 10 feet', array['More than 6 feet', 'More than 20 feet', 'More than 10 feet', 'More than 4 feet']::text[], 2, 'Scaffolds have their own 10-foot rule in 1926.451(g), different from the 6-foot rule for other walking/working surfaces.', md5('academykb:section:cfr:1926.451(g)')::uuid, '29 CFR 1926.451(g)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 19),
  (md5('academykb:item:sc-capacity')::uuid, 'sc-capacity', 'question', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'medium', 'Each scaffold and scaffold component must support its own weight and at least how many times the maximum intended load?', '4 times', array['4 times', '10 times', '3 times', '2 times']::text[], 0, null, md5('academykb:section:cfr:1926.451(a)')::uuid, '29 CFR 1926.451(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 20),
  (md5('academykb:item:ld-extend')::uuid, 'ld-extend', 'question', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'easy', 'When a portable ladder is used to reach an upper landing, how far must the side rails extend above the landing?', 'At least 3 feet', array['At least 2 feet', 'At least 5 feet', 'At least 3 feet', 'At least 1 foot']::text[], 2, 'If the ladder isn''t long enough, it must be secured at the top and a grab device provided.', md5('academykb:section:cfr:1926.1053(b)')::uuid, '29 CFR 1926.1053(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 21),
  (md5('academykb:item:ld-angle')::uuid, 'ld-angle', 'question', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'medium', 'For a non-self-supporting ladder, the horizontal distance from the top support to the foot should be about what fraction of the ladder''s working length?', 'One-quarter (the 4-to-1 rule)', array['One-half', 'Equal to the working length', 'One-tenth', 'One-quarter (the 4-to-1 rule)']::text[], 3, null, md5('academykb:section:cfr:1926.1053(b)')::uuid, '29 CFR 1926.1053(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 22),
  (md5('academykb:item:ld-capacity')::uuid, 'ld-capacity', 'question', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'medium', 'A self-supporting portable ladder (other than extra-heavy-duty type 1A) must support at least how many times its maximum intended load?', 'Four times', array['Three times', 'Six times', 'Four times', 'Two times']::text[], 2, null, md5('academykb:section:cfr:1926.1053(a)')::uuid, '29 CFR 1926.1053(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 23),
  (md5('academykb:item:ld-slip')::uuid, 'ld-slip', 'question', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'easy', 'Ladders must be kept free of what?', 'Oil, grease and other slipping hazards', array['Paint of any kind', 'Tool trays', 'Labels and stickers', 'Oil, grease and other slipping hazards']::text[], 3, null, md5('academykb:section:cfr:1926.1053(b)')::uuid, '29 CFR 1926.1053(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 24),
  (md5('academykb:item:ld-purpose')::uuid, 'ld-purpose', 'question', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'easy', 'True or false under OSHA: a ladder may be used for any purpose as long as it is in good condition.', 'False. Ladders may be used only for the purpose for which they were designed.', array['True, if the foreman approves', 'True for job-made ladders only', 'True', 'False. Ladders may be used only for the purpose for which they were designed.']::text[], 3, null, md5('academykb:section:cfr:1926.1053(b)')::uuid, '29 CFR 1926.1053(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 25),
  (md5('academykb:item:st-handrail')::uuid, 'st-handrail', 'question', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'medium', 'On a construction site, a stairway needs at least one handrail when it has how many risers or how much rise, whichever is less?', 'Four or more risers, or more than 30 inches of rise', array['Six or more risers, or more than 48 inches', 'Only above 10 feet', 'Two or more risers', 'Four or more risers, or more than 30 inches of rise']::text[], 3, null, md5('academykb:section:cfr:1926.1052(c)')::uuid, '29 CFR 1926.1052(c)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 26),
  (md5('academykb:item:st-angle')::uuid, 'st-angle', 'question', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'hard', 'At what angle range from horizontal must jobsite stairs be installed?', 'Between 30° and 50°', array['Between 45° and 75°', 'Any angle under 60°', 'Between 30° and 50°', 'Between 20° and 40°']::text[], 2, null, md5('academykb:section:cfr:1926.1052(a)')::uuid, '29 CFR 1926.1052(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 27),
  (md5('academykb:item:st-variation')::uuid, 'st-variation', 'question', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'hard', 'In a jobsite stairway system, how much may riser height or tread depth vary?', 'Not over 1/4 inch', array['Not over 1/4 inch', 'Not over 1 inch', 'Not over 1/2 inch', 'Not over 1/8 inch']::text[], 0, null, md5('academykb:section:cfr:1926.1052(a)')::uuid, '29 CFR 1926.1052(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 28),
  (md5('academykb:item:st-rail-height')::uuid, 'st-rail-height', 'question', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'medium', 'How high must stairrails installed after March 15, 1991 be, measured from the tread surface in line with the riser face?', 'Not less than 36 inches', array['Not less than 36 inches', 'Not less than 42 inches', 'Not less than 34 inches', 'Not less than 30 inches']::text[], 0, null, md5('academykb:section:cfr:1926.1052(c)')::uuid, '29 CFR 1926.1052(c)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 29),
  (md5('academykb:item:st-landings')::uuid, 'st-landings', 'question', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'hard', 'Temporary stairways that won''t be part of the finished structure need landings at least 30 inches deep and 22 inches wide at least every how much vertical rise?', '12 feet', array['10 feet', '20 feet', '12 feet', '6 feet']::text[], 2, null, md5('academykb:section:cfr:1926.1052(a)')::uuid, '29 CFR 1926.1052(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 30),
  (md5('academykb:item:ld-training')::uuid, 'ld-training', 'question', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'medium', 'Who must train employees who use ladders and stairways, as applicable?', 'A competent person', array['The ladder manufacturer', 'The general contractor''s accountant', 'Any experienced coworker', 'A competent person']::text[], 3, null, md5('academykb:section:cfr:1926.1060')::uuid, '29 CFR 1926.1060', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 31),
  (md5('academykb:item:ld-card-4to1')::uuid, 'ld-card-4to1', 'flashcard', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'medium', 'Ladder 4-to-1 rule', 'Set the foot about one-quarter of the working length away from the top support (29 CFR 1926.1053(b)(5)(i)).', null, null, null, md5('academykb:section:cfr:1926.1053(b)')::uuid, '29 CFR 1926.1053(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 32),
  (md5('academykb:item:ld-card-3ft')::uuid, 'ld-card-3ft', 'flashcard', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'medium', 'Ladder extension above a landing', 'Side rails at least 3 feet above the upper landing, or secure the top and add a grab device (29 CFR 1926.1053(b)(1)).', null, null, null, md5('academykb:section:cfr:1926.1053(b)')::uuid, '29 CFR 1926.1053(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 33),
  (md5('academykb:item:sc-card-10ft')::uuid, 'sc-card-10ft', 'flashcard', 'osha-ladders-stairs', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'roofing', 'siding', 'framing', 'electrical', 'windows-doors', 'insulation']::text[], null, 'medium', 'Scaffold fall protection height', 'More than 10 feet above a lower level (29 CFR 1926.451(g)(1)).', null, null, null, md5('academykb:section:cfr:1926.451(g)')::uuid, '29 CFR 1926.451(g)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 34),
  (md5('academykb:item:ex-egress-depth')::uuid, 'ex-egress-depth', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'easy', 'A stairway, ladder, ramp or other safe means of egress is required in trench excavations of what depth?', '4 feet or more', array['5 feet or more', '8 feet or more', '4 feet or more', '3 feet or more']::text[], 2, null, md5('academykb:section:cfr:1926.651(c)')::uuid, '29 CFR 1926.651(c)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 35),
  (md5('academykb:item:ex-egress-travel')::uuid, 'ex-egress-travel', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'medium', 'Means of egress in a trench must be placed so employees travel no more than how far laterally to reach it?', '25 feet', array['25 feet', '50 feet', '100 feet', '10 feet']::text[], 0, null, md5('academykb:section:cfr:1926.651(c)')::uuid, '29 CFR 1926.651(c)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 36),
  (md5('academykb:item:ex-protective-5ft')::uuid, 'ex-protective-5ft', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'medium', 'A cave-in protective system is not required when the excavation is less than how deep and a competent person finds no indication of a potential cave-in?', '5 feet', array['5 feet', '6 feet', '10 feet', '4 feet']::text[], 0, 'Excavations made entirely in stable rock are the other exception in 1926.652(a)(1).', md5('academykb:section:cfr:1926.652(a)')::uuid, '29 CFR 1926.652(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 37),
  (md5('academykb:item:ex-spoils')::uuid, 'ex-spoils', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'easy', 'How far back from the edge of an excavation must excavated material (spoils) and equipment be kept, unless retaining devices are used?', 'At least 2 feet', array['At least 5 feet', 'At least 10 feet', 'At least 2 feet', 'At least 1 foot']::text[], 2, null, md5('academykb:section:cfr:1926.651(j)')::uuid, '29 CFR 1926.651(j)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 38),
  (md5('academykb:item:ex-inspect-who')::uuid, 'ex-inspect-who', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'medium', 'Who must make daily inspections of excavations, adjacent areas and protective systems?', 'A competent person', array['The excavator operator', 'The utility locator', 'The property owner', 'A competent person']::text[], 3, null, md5('academykb:section:cfr:1926.651(k)')::uuid, '29 CFR 1926.651(k)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 39),
  (md5('academykb:item:ex-inspect-rain')::uuid, 'ex-inspect-rain', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'medium', 'Besides before work and as needed during the shift, when else must excavations be inspected?', 'After every rainstorm or other hazard-increasing occurrence', array['Only when OSHA visits', 'Only at the end of the job', 'Only once a week', 'After every rainstorm or other hazard-increasing occurrence']::text[], 3, null, md5('academykb:section:cfr:1926.651(k)')::uuid, '29 CFR 1926.651(k)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 40),
  (md5('academykb:item:ex-remove-employees')::uuid, 'ex-remove-employees', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'medium', 'If a competent person finds evidence of a possible cave-in, what must happen?', 'Exposed employees must be removed from the hazardous area until precautions are taken', array['The finding is logged at the end of the day', 'Only the operator must leave', 'Work may continue if employees wear hard hats', 'Exposed employees must be removed from the hazardous area until precautions are taken']::text[], 3, null, md5('academykb:section:cfr:1926.651(k)')::uuid, '29 CFR 1926.651(k)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 41),
  (md5('academykb:item:ex-oxygen')::uuid, 'ex-oxygen', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'hard', 'OSHA''s excavation rule treats an atmosphere as oxygen deficient below what oxygen level?', '19.5 percent', array['19.5 percent', '21 percent', '23.5 percent', '16 percent']::text[], 0, null, md5('academykb:section:cfr:1926.651(g)')::uuid, '29 CFR 1926.651(g)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 42),
  (md5('academykb:item:ex-atmosphere-test')::uuid, 'ex-atmosphere-test', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'hard', 'Where a hazardous atmosphere could reasonably be expected, the atmosphere must be tested before employees enter excavations deeper than what?', '4 feet', array['4 feet', '10 feet', '6 feet', '2 feet']::text[], 0, null, md5('academykb:section:cfr:1926.651(g)')::uuid, '29 CFR 1926.651(g)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 43),
  (md5('academykb:item:ex-flammable')::uuid, 'ex-flammable', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'hard', 'Precautions such as ventilation must keep flammable gas in an excavation from exceeding what level?', '20 percent of the lower flammable limit', array['20 percent of the lower flammable limit', '50 percent of the lower flammable limit', '100 percent of the lower flammable limit', '10 percent of the lower flammable limit']::text[], 0, null, md5('academykb:section:cfr:1926.651(g)')::uuid, '29 CFR 1926.651(g)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 44),
  (md5('academykb:item:ex-utilities-24h')::uuid, 'ex-utilities-24h', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'medium', 'If utility companies can''t respond to a locate request within 24 hours (unless state or local law sets a longer period), what may the employer do?', 'Proceed with caution, using detection equipment or other acceptable means to locate utilities', array['Dig anywhere at normal speed', 'Wait indefinitely; digging is prohibited', 'Ask the homeowner to mark the lines', 'Proceed with caution, using detection equipment or other acceptable means to locate utilities']::text[], 3, 'Many states also have their own one-call (811) law with specific notice times. Check yours.', md5('academykb:section:cfr:1926.651(b)')::uuid, '29 CFR 1926.651(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 45),
  (md5('academykb:item:ex-traffic')::uuid, 'ex-traffic', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'easy', 'What must employees exposed to public vehicular traffic around an excavation wear?', 'Warning vests or other high-visibility garments', array['Hearing protection', 'Respirators', 'Steel-toe boots only', 'Warning vests or other high-visibility garments']::text[], 3, null, md5('academykb:section:cfr:1926.651(d)')::uuid, '29 CFR 1926.651(d)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 46),
  (md5('academykb:item:ex-loads')::uuid, 'ex-loads', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'easy', 'May an employee stand underneath a load being handled by a backhoe or other digging equipment?', 'No', array['Yes, with a hard hat', 'Yes, if the operator can see them', 'Yes, for short periods', 'No']::text[], 3, null, md5('academykb:section:cfr:1926.651(e)')::uuid, '29 CFR 1926.651(e)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 47),
  (md5('academykb:item:ex-ramps')::uuid, 'ex-ramps', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'medium', 'Who must design structural ramps used only by employees to get in and out of an excavation?', 'A competent person', array['A registered professional engineer in every case', 'The ramp manufacturer', 'No design is needed', 'A competent person']::text[], 3, null, md5('academykb:section:cfr:1926.651(c)')::uuid, '29 CFR 1926.651(c)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 48),
  (md5('academykb:item:ex-water-monitor')::uuid, 'ex-water-monitor', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'medium', 'If water removal equipment is used to control water in an excavation, who must monitor it?', 'A competent person', array['The pump rental company', 'Any laborer', 'Nobody, once it is running', 'A competent person']::text[], 3, null, md5('academykb:section:cfr:1926.651(h)')::uuid, '29 CFR 1926.651(h)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 49),
  (md5('academykb:item:ex-walkway')::uuid, 'ex-walkway', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'medium', 'Walkways over excavations need guardrails when they are how high above lower levels?', '6 feet or more', array['6 feet or more', 'Guardrails are never required on walkways', '10 feet or more', '4 feet or more']::text[], 0, null, md5('academykb:section:cfr:1926.651(l)')::uuid, '29 CFR 1926.651(l)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 50),
  (md5('academykb:item:ex-footing')::uuid, 'ex-footing', 'question', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'hard', 'Excavating below the base of a nearby foundation that could endanger employees is allowed only in limited cases. Which is one of them?', 'A support system such as underpinning is provided', array['The foundation is less than 10 years old', 'The owner gives written permission', 'The excavation will be open less than one day', 'A support system such as underpinning is provided']::text[], 3, null, md5('academykb:section:cfr:1926.651(i)')::uuid, '29 CFR 1926.651(i)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 51),
  (md5('academykb:item:ex-card-numbers')::uuid, 'ex-card-numbers', 'flashcard', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'medium', 'Trench numbers to remember (OSHA)', 'Egress at 4 ft deep within 25 ft of travel; protective system at 5 ft (unless stable rock); spoils 2 ft back from the edge (29 CFR 1926.651–652).', null, null, null, md5('academykb:section:cfr:1926.651(c)')::uuid, '29 CFR 1926.651(c)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 52),
  (md5('academykb:item:ex-card-inspect')::uuid, 'ex-card-inspect', 'flashcard', 'osha-excavation', array['excavation', 'concrete', 'foundations', 'plumbing', 'landscaping', 'basements', 'asphalt-paving', 'general-contracting']::text[], null, 'medium', 'Excavation inspections', 'Daily by a competent person, before work starts, as needed during the shift, and after every rainstorm (29 CFR 1926.651(k)).', null, null, null, md5('academykb:section:cfr:1926.651(k)')::uuid, '29 CFR 1926.651(k)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 53),
  (md5('academykb:item:gen-inspections')::uuid, 'gen-inspections', 'question', 'osha-general', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'electrical', 'demolition', 'framing', 'concrete', 'masonry']::text[], null, 'medium', 'Under 29 CFR 1926.20, who must make frequent and regular inspections of job sites, materials and equipment?', 'Competent persons designated by the employer', array['OSHA compliance officers', 'The equipment dealer', 'The building inspector', 'Competent persons designated by the employer']::text[], 3, null, md5('academykb:section:cfr:1926.20(b)')::uuid, '29 CFR 1926.20(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 54),
  (md5('academykb:item:gen-unsafe-equipment')::uuid, 'gen-unsafe-equipment', 'question', 'osha-general', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'electrical', 'demolition', 'framing', 'concrete', 'masonry']::text[], null, 'medium', 'What must happen to a tool or machine that doesn''t comply with OSHA''s construction rules?', 'Tag it or lock its controls as unsafe, or physically remove it', array['Report it at the next annual review', 'Let only experienced workers use it', 'Use it carefully until the job ends', 'Tag it or lock its controls as unsafe, or physically remove it']::text[], 3, null, md5('academykb:section:cfr:1926.20(b)')::uuid, '29 CFR 1926.20(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 55),
  (md5('academykb:item:gen-qualified-operators')::uuid, 'gen-qualified-operators', 'question', 'osha-general', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'electrical', 'demolition', 'framing', 'concrete', 'masonry']::text[], null, 'easy', 'Who may the employer permit to operate equipment and machinery?', 'Only employees qualified by training or experience', array['Anyone with a driver''s license', 'Any employee who asks', 'Anyone over 18', 'Only employees qualified by training or experience']::text[], 3, null, md5('academykb:section:cfr:1926.20(b)')::uuid, '29 CFR 1926.20(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 56),
  (md5('academykb:item:gen-ppe-each')::uuid, 'gen-ppe-each', 'question', 'osha-general', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'electrical', 'demolition', 'framing', 'concrete', 'masonry']::text[], null, 'medium', 'If an employer fails to provide required PPE to three employees, how many violations can OSHA consider that?', 'Each failure for each employee may be a separate violation', array['One violation total', 'None, if PPE was offered verbally', 'Only a warning', 'Each failure for each employee may be a separate violation']::text[], 3, null, md5('academykb:section:cfr:1926.20(f)')::uuid, '29 CFR 1926.20(f)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 57),
  (md5('academykb:item:gen-specific-general')::uuid, 'gen-specific-general', 'question', 'osha-general', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'electrical', 'demolition', 'framing', 'concrete', 'masonry']::text[], null, 'hard', 'When both a specific OSHA standard and a general standard cover the same condition, which governs?', 'The specific standard prevails', array['The less strict one', 'Whichever the employer chooses', 'The general standard prevails', 'The specific standard prevails']::text[], 3, null, md5('academykb:section:cfr:1926.20(d)')::uuid, '29 CFR 1926.20(d)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 58),
  (md5('academykb:item:gen-training-duty')::uuid, 'gen-training-duty', 'question', 'osha-general', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'electrical', 'demolition', 'framing', 'concrete', 'masonry']::text[], null, 'medium', 'What must the employer instruct each employee in under 29 CFR 1926.21?', 'Recognizing and avoiding unsafe conditions and the regulations for their work', array['Company sales goals', 'How to file insurance claims', 'First aid certification for all employees', 'Recognizing and avoiding unsafe conditions and the regulations for their work']::text[], 3, null, md5('academykb:section:cfr:1926.21')::uuid, '29 CFR 1926.21', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 59)
insert into public.academy_kb_items (id, key, kind, deck, trades, state_code, difficulty, prompt, answer, options, correct, explanation, section_id, citation, basis, origin, status, exam_tags, sort_order) values
  (md5('academykb:item:gen-hardhat')::uuid, 'gen-hardhat', 'question', 'osha-general', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'electrical', 'demolition', 'framing', 'concrete', 'masonry']::text[], null, 'easy', 'When must employees wear protective helmets (hard hats)?', 'Where there is a possible danger of head injury from impact, falling or flying objects, or electrical shock and burns', array['Only above 6 feet', 'Only when the owner requires it', 'Only on commercial jobs', 'Where there is a possible danger of head injury from impact, falling or flying objects, or electrical shock and burns']::text[], 3, null, md5('academykb:section:cfr:1926.100')::uuid, '29 CFR 1926.100', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 60),
  (md5('academykb:item:gen-side-shields')::uuid, 'gen-side-shields', 'question', 'osha-general', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'electrical', 'demolition', 'framing', 'concrete', 'masonry']::text[], null, 'medium', 'When does eye protection need side protection?', 'When there is a hazard from flying objects', array['Only when grinding metal', 'Never; safety glasses alone are enough', 'Only outdoors', 'When there is a hazard from flying objects']::text[], 3, null, md5('academykb:section:cfr:1926.102(a)')::uuid, '29 CFR 1926.102(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 61),
  (md5('academykb:item:gen-prescription')::uuid, 'gen-prescription', 'question', 'osha-general', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'electrical', 'demolition', 'framing', 'concrete', 'masonry']::text[], null, 'medium', 'An employee wears prescription glasses on a job with eye hazards. What is required?', 'Eye protection that includes the prescription, or that fits over the glasses without disturbing them', array['The employee must switch to contacts', 'The employee can''t work there', 'Regular prescription glasses are enough', 'Eye protection that includes the prescription, or that fits over the glasses without disturbing them']::text[], 3, null, md5('academykb:section:cfr:1926.102(a)')::uuid, '29 CFR 1926.102(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 62),
  (md5('academykb:item:gen-gfci')::uuid, 'gen-gfci', 'question', 'osha-general', array['electrical', 'general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling']::text[], null, 'medium', 'On construction sites, which receptacle outlets must have GFCI protection when not part of the building''s permanent wiring and in use by employees (unless an assured grounding program is used)?', 'All 120-volt, single-phase, 15- and 20-ampere outlets', array['Only outlets within 6 feet of water', 'Only outlets on generators', 'Only 240-volt outlets', 'All 120-volt, single-phase, 15- and 20-ampere outlets']::text[], 3, null, md5('academykb:section:cfr:1926.404(b)')::uuid, '29 CFR 1926.404(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 63),
  (md5('academykb:item:gen-aegcp')::uuid, 'gen-aegcp', 'question', 'osha-general', array['electrical', 'general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling']::text[], null, 'hard', 'What is OSHA''s alternative to GFCIs for protecting employees from ground faults on construction sites?', 'An assured equipment grounding conductor program', array['Using only extension cords under 50 feet', 'Daily visual checks with no records', 'Rubber mats at every outlet', 'An assured equipment grounding conductor program']::text[], 3, null, md5('academykb:section:cfr:1926.404(b)')::uuid, '29 CFR 1926.404(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 64),
  (md5('academykb:item:gen-generator')::uuid, 'gen-generator', 'question', 'osha-general', array['electrical', 'general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling']::text[], null, 'hard', 'Which generator receptacles are exempt from the jobsite GFCI requirement?', 'Two-wire, single-phase portable or vehicle-mounted generators rated 5kW or less with conductors insulated from the frame', array['Any generator', 'None', 'Generators over 10kW', 'Two-wire, single-phase portable or vehicle-mounted generators rated 5kW or less with conductors insulated from the frame']::text[], 3, null, md5('academykb:section:cfr:1926.404(b)')::uuid, '29 CFR 1926.404(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 65),
  (md5('academykb:item:demo-survey')::uuid, 'demo-survey', 'question', 'osha-general', array['demolition', 'general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling']::text[], null, 'medium', 'Before demolition starts, what must a competent person perform, with written evidence kept?', 'An engineering survey of the structure', array['A soil boring', 'A neighbor notification', 'A lead paint test only', 'An engineering survey of the structure']::text[], 3, null, md5('academykb:section:cfr:1926.850')::uuid, '29 CFR 1926.850', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 66),
  (md5('academykb:item:demo-utilities')::uuid, 'demo-utilities', 'question', 'osha-general', array['demolition', 'general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling']::text[], null, 'medium', 'Before demolition, where must electric, gas, water, sewer and other service lines be shut off, capped or controlled?', 'Outside the building line', array['At the main panel inside', 'They can stay live until the end', 'At the street only for gas', 'Outside the building line']::text[], 3, null, md5('academykb:section:cfr:1926.850')::uuid, '29 CFR 1926.850', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 67),
  (md5('academykb:item:gen-card-gfci')::uuid, 'gen-card-gfci', 'flashcard', 'osha-general', array['electrical', 'general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling']::text[], null, 'medium', 'Jobsite GFCI rule', '120-volt, single-phase, 15/20-amp temporary outlets in use need GFCIs, or use an assured equipment grounding conductor program (29 CFR 1926.404(b)(1)).', null, null, null, md5('academykb:section:cfr:1926.404(b)')::uuid, '29 CFR 1926.404(b)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'general-contractor-knowledge-practice']::text[], 68),
  (md5('academykb:item:hh-lead-scope')::uuid, 'hh-lead-scope', 'question', 'osha-health-hazards', array['painting', 'general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling']::text[], null, 'medium', 'OSHA''s construction lead standard (29 CFR 1926.62) defines construction work to include what?', 'Construction, alteration and repair, including painting and decorating', array['Only demolition', 'Only work on government buildings', 'Only new construction', 'Construction, alteration and repair, including painting and decorating']::text[], 3, null, md5('academykb:section:cfr:1926.62(a)')::uuid, '29 CFR 1926.62(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'lead-safe-renovation-practice']::text[], 69),
  (md5('academykb:item:hh-asbestos-roof')::uuid, 'hh-asbestos-roof', 'question', 'osha-health-hazards', array['roofing', 'demolition', 'general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling']::text[], null, 'hard', 'Which materials are excluded from OSHA''s construction asbestos standard?', 'Asbestos-containing asphalt roof coatings, cements and mastics', array['Pipe insulation', 'Spray-on fireproofing', 'Asbestos floor tile', 'Asbestos-containing asphalt roof coatings, cements and mastics']::text[], 3, null, md5('academykb:section:cfr:1926.1101(a)')::uuid, '29 CFR 1926.1101(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'lead-safe-renovation-practice']::text[], 70),
  (md5('academykb:item:hh-silica-threshold')::uuid, 'hh-silica-threshold', 'question', 'osha-health-hazards', array['concrete', 'masonry', 'tile', 'cabinets-countertops', 'demolition', 'general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling']::text[], null, 'hard', 'The silica standard for construction applies except where exposure will stay below what level under any foreseeable conditions?', '25 micrograms per cubic meter as an 8-hour TWA', array['100 micrograms per cubic meter', 'There is no threshold', '50 micrograms per cubic meter as a 1-hour average', '25 micrograms per cubic meter as an 8-hour TWA']::text[], 3, null, md5('academykb:section:cfr:1926.1153(a)')::uuid, '29 CFR 1926.1153(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'lead-safe-renovation-practice']::text[], 71),
  (md5('academykb:item:hh-silica-table1')::uuid, 'hh-silica-table1', 'question', 'osha-health-hazards', array['concrete', 'masonry', 'tile', 'demolition', 'general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling']::text[], null, 'medium', 'For a task listed on the silica standard''s Table 1, what must the employer do unless it assesses and limits exposure another way?', 'Fully implement the engineering controls, work practices and respiratory protection listed for that task', array['Work only outdoors', 'Nothing, if the task takes under 4 hours', 'Give employees dust masks of their choice', 'Fully implement the engineering controls, work practices and respiratory protection listed for that task']::text[], 3, null, md5('academykb:section:cfr:1926.1153(c)')::uuid, '29 CFR 1926.1153(c)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'lead-safe-renovation-practice']::text[], 72),
  (md5('academykb:item:hh-silica-wet')::uuid, 'hh-silica-wet', 'question', 'osha-health-hazards', array['concrete', 'masonry', 'tile', 'general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling']::text[], null, 'medium', 'When wet methods are used to control silica dust, how much water must be applied?', 'Enough to minimize the release of visible dust', array['At least 1 gallon per minute in all cases', 'Just enough to dampen the blade once', 'Water is optional', 'Enough to minimize the release of visible dust']::text[], 3, null, md5('academykb:section:cfr:1926.1153(c)')::uuid, '29 CFR 1926.1153(c)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'lead-safe-renovation-practice']::text[], 73),
  (md5('academykb:item:hh-card-silica')::uuid, 'hh-card-silica', 'flashcard', 'osha-health-hazards', array['concrete', 'masonry', 'tile', 'general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling']::text[], null, 'medium', 'Silica: Table 1', 'For listed tasks (saws, grinders, drills, etc.), follow the controls on Table 1 exactly, or measure and limit exposure under paragraph (d) (29 CFR 1926.1153(c)).', null, null, null, md5('academykb:section:cfr:1926.1153(c)')::uuid, '29 CFR 1926.1153(c)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'lead-safe-renovation-practice']::text[], 74),
  (md5('academykb:item:rk-fatality')::uuid, 'rk-fatality', 'question', 'osha-recordkeeping', '{}'::text[], null, 'easy', 'How soon must an employer report a work-related fatality to OSHA?', 'Within 8 hours', array['Within 24 hours', 'Within 7 days', 'Within 3 days', 'Within 8 hours']::text[], 3, null, md5('academykb:section:cfr:1904.39(a)')::uuid, '29 CFR 1904.39(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'business-law-practice', 'general-contractor-knowledge-practice']::text[], 75),
  (md5('academykb:item:rk-hospital')::uuid, 'rk-hospital', 'question', 'osha-recordkeeping', '{}'::text[], null, 'medium', 'How soon must an employer report an in-patient hospitalization, amputation or loss of an eye to OSHA?', 'Within 24 hours', array['Within 24 hours', 'At the end of the year', 'Within 72 hours', 'Within 8 hours']::text[], 0, null, md5('academykb:section:cfr:1904.39(a)')::uuid, '29 CFR 1904.39(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'business-law-practice', 'general-contractor-knowledge-practice']::text[], 76),
  (md5('academykb:item:rk-how')::uuid, 'rk-how', 'question', 'osha-recordkeeping', '{}'::text[], null, 'medium', 'Which is an accepted way to report a fatality or serious injury to OSHA?', 'Call 1-800-321-OSHA (or the nearest area office, or report online)', array['Tell your insurance agent', 'Post a notice at the job site', 'Mail a letter within 30 days', 'Call 1-800-321-OSHA (or the nearest area office, or report online)']::text[], 3, null, md5('academykb:section:cfr:1904.39(a)')::uuid, '29 CFR 1904.39(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'business-law-practice', 'general-contractor-knowledge-practice']::text[], 77),
  (md5('academykb:item:rk-small-exempt')::uuid, 'rk-small-exempt', 'question', 'osha-recordkeeping', '{}'::text[], null, 'medium', 'A company had no more than 10 employees at any time last calendar year. Does it have to keep OSHA injury and illness records?', 'Generally no, unless OSHA or BLS tells it in writing to keep them, but it must still report serious injuries', array['Yes, always', 'Only if it is incorporated', 'No, and it never has to report anything', 'Generally no, unless OSHA or BLS tells it in writing to keep them, but it must still report serious injuries']::text[], 3, null, md5('academykb:section:cfr:1904.1')::uuid, '29 CFR 1904.1', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'business-law-practice', 'general-contractor-knowledge-practice']::text[], 78),
  (md5('academykb:item:rk-company-size')::uuid, 'rk-company-size', 'question', 'osha-recordkeeping', '{}'::text[], null, 'hard', 'Is OSHA''s small-employer recordkeeping exemption based on each job site or the whole company?', 'The number of employees in the entire company', array['Each job site separately', 'Each crew separately', 'Only full-time employees at the office', 'The number of employees in the entire company']::text[], 3, null, md5('academykb:section:cfr:1904.1')::uuid, '29 CFR 1904.1', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'business-law-practice', 'general-contractor-knowledge-practice']::text[], 79),
  (md5('academykb:item:rk-card')::uuid, 'rk-card', 'flashcard', 'osha-recordkeeping', '{}'::text[], null, 'medium', 'OSHA reporting deadlines', 'Fatality: 8 hours. In-patient hospitalization, amputation or loss of an eye: 24 hours (29 CFR 1904.39).', null, null, null, md5('academykb:section:cfr:1904.39(a)')::uuid, '29 CFR 1904.39(a)', 'regulatory', 'original', 'approved', array['construction-safety-practice', 'business-law-practice', 'general-contractor-knowledge-practice']::text[], 80),
  (md5('academykb:item:rrp-applies')::uuid, 'rrp-applies', 'question', 'epa-lead-rrp', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'windows-doors', 'kitchens', 'bathrooms', 'flooring', 'siding', 'basements']::text[], null, 'easy', 'The EPA Renovation, Repair and Painting Rule applies to which work?', 'Renovations for compensation in target housing and child-occupied facilities', array['Only demolition of commercial buildings', 'Any work on homes built after 1978', 'Only work a homeowner does on their own house', 'Renovations for compensation in target housing and child-occupied facilities']::text[], 3, 'Target housing is generally housing built before 1978, with some exceptions.', md5('academykb:section:cfr:745.82')::uuid, '40 CFR 745.82', 'regulatory', 'original', 'approved', array['lead-safe-renovation-practice']::text[], 81),
  (md5('academykb:item:rrp-threshold')::uuid, 'rrp-threshold', 'question', 'epa-lead-rrp', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'windows-doors', 'kitchens', 'bathrooms', 'flooring', 'siding', 'basements']::text[], null, 'hard', 'An RRP exemption applies when components are shown to be free of paint containing lead at or above what level?', '1.0 mg/cm² or 0.5% by weight', array['5.0 mg/cm² or 2% by weight', '0.1 mg/cm² or 0.05% by weight', 'Any detectable amount', '1.0 mg/cm² or 0.5% by weight']::text[], 3, null, md5('academykb:section:cfr:745.82')::uuid, '40 CFR 745.82', 'regulatory', 'original', 'approved', array['lead-safe-renovation-practice']::text[], 82),
  (md5('academykb:item:rrp-test-kit')::uuid, 'rrp-test-kit', 'question', 'epa-lead-rrp', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'windows-doors', 'kitchens', 'bathrooms', 'flooring', 'siding', 'basements']::text[], null, 'medium', 'Who may use an EPA-recognized test kit to determine that components are lead-free for RRP purposes?', 'A certified renovator', array['The paint store', 'Any laborer on the crew', 'Any homeowner', 'A certified renovator']::text[], 3, null, md5('academykb:section:cfr:745.82')::uuid, '40 CFR 745.82', 'regulatory', 'original', 'approved', array['lead-safe-renovation-practice']::text[], 83),
  (md5('academykb:item:rrp-pamphlet-60')::uuid, 'rrp-pamphlet-60', 'question', 'epa-lead-rrp', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'windows-doors', 'kitchens', 'bathrooms', 'flooring', 'siding', 'basements']::text[], null, 'medium', 'How early may a firm give the owner the lead pamphlet before starting renovation in a dwelling unit of target housing?', 'No more than 60 days before work begins', array['Any time in the past year', 'On the day work starts only', 'After the job is complete', 'No more than 60 days before work begins']::text[], 3, null, md5('academykb:section:cfr:745.84(a)')::uuid, '40 CFR 745.84(a)', 'regulatory', 'original', 'approved', array['lead-safe-renovation-practice']::text[], 84),
  (md5('academykb:item:rrp-mailing')::uuid, 'rrp-mailing', 'question', 'epa-lead-rrp', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'windows-doors', 'kitchens', 'bathrooms', 'flooring', 'siding', 'basements']::text[], null, 'hard', 'If the firm mails the lead pamphlet instead of getting a signed acknowledgment, what must it obtain?', 'A certificate of mailing at least 7 days before the renovation', array['A notarized affidavit', 'Nothing; mailing alone is enough', 'A text message receipt', 'A certificate of mailing at least 7 days before the renovation']::text[], 3, null, md5('academykb:section:cfr:745.84(a)')::uuid, '40 CFR 745.84(a)', 'regulatory', 'original', 'approved', array['lead-safe-renovation-practice']::text[], 85),
  (md5('academykb:item:rrp-who')::uuid, 'rrp-who', 'question', 'epa-lead-rrp', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'windows-doors', 'kitchens', 'bathrooms', 'flooring', 'siding', 'basements']::text[], null, 'easy', 'Who must perform RRP-covered renovations?', 'Certified firms using certified renovators', array['Any licensed contractor', 'Any painter with 5 years of experience', 'Only the homeowner', 'Certified firms using certified renovators']::text[], 3, null, md5('academykb:section:cfr:745.85(a)')::uuid, '40 CFR 745.85(a)', 'regulatory', 'original', 'approved', array['lead-safe-renovation-practice']::text[], 86),
  (md5('academykb:item:rrp-signs')::uuid, 'rrp-signs', 'question', 'epa-lead-rrp', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'windows-doors', 'kitchens', 'bathrooms', 'flooring', 'siding', 'basements']::text[], null, 'medium', 'How long must RRP warning signs stay posted?', 'Until the renovation and the post-renovation cleaning verification are complete', array['Only on the first day', 'For 30 days after the job', 'Only while dust is visible', 'Until the renovation and the post-renovation cleaning verification are complete']::text[], 3, null, md5('academykb:section:cfr:745.85(a)')::uuid, '40 CFR 745.85(a)', 'regulatory', 'original', 'approved', array['lead-safe-renovation-practice']::text[], 87),
  (md5('academykb:item:rrp-containment')::uuid, 'rrp-containment', 'question', 'epa-lead-rrp', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'windows-doors', 'kitchens', 'bathrooms', 'flooring', 'siding', 'basements']::text[], null, 'medium', 'Before beginning an RRP renovation, what must the firm do with the work area?', 'Isolate it so no dust or debris leaves while work is done', array['Wet down the outside of the house', 'Nothing until demolition starts', 'Open windows for ventilation', 'Isolate it so no dust or debris leaves while work is done']::text[], 3, null, md5('academykb:section:cfr:745.85(a)')::uuid, '40 CFR 745.85(a)', 'regulatory', 'original', 'approved', array['lead-safe-renovation-practice']::text[], 88),
  (md5('academykb:item:rrp-firm-90')::uuid, 'rrp-firm-90', 'question', 'epa-lead-rrp', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting']::text[], null, 'medium', 'After receiving a firm''s certification application, how long does EPA have to act on it?', '90 days', array['30 days', '90 days', '1 year', '10 days']::text[], 1, null, md5('academykb:section:cfr:745.89(a)')::uuid, '40 CFR 745.89(a)', 'regulatory', 'original', 'approved', array['lead-safe-renovation-practice']::text[], 89),
  (md5('academykb:item:rrp-firm-5yr')::uuid, 'rrp-firm-5yr', 'question', 'epa-lead-rrp', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'windows-doors', 'kitchens', 'bathrooms', 'flooring', 'siding', 'basements']::text[], null, 'medium', 'An EPA firm certification expires no more than how long after approval?', '5 years', array['3 years', 'It never expires', '5 years', '1 year']::text[], 2, null, md5('academykb:section:cfr:745.89(a)')::uuid, '40 CFR 745.89(a)', 'regulatory', 'original', 'approved', array['lead-safe-renovation-practice']::text[], 90),
  (md5('academykb:item:rrp-state-programs')::uuid, 'rrp-state-programs', 'question', 'epa-lead-rrp', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'windows-doors', 'kitchens', 'bathrooms', 'flooring', 'siding', 'basements']::text[], null, 'hard', 'Where does an EPA firm certification let a firm perform covered renovations?', 'In any state or tribal area that does not have its own EPA-authorized renovation program', array['In every state, no exceptions', 'Only on federal property', 'Only in the firm''s home state', 'In any state or tribal area that does not have its own EPA-authorized renovation program']::text[], 3, 'Some states run their own authorized programs with their own certification. Check where you work.', md5('academykb:section:cfr:745.89(a)')::uuid, '40 CFR 745.89(a)', 'regulatory', 'original', 'approved', array['lead-safe-renovation-practice']::text[], 91),
  (md5('academykb:item:rrp-card')::uuid, 'rrp-card', 'flashcard', 'epa-lead-rrp', array['general-contracting', 'handyman', 'additions', 'interior-remodeling', 'exterior-remodeling', 'commercial-remodeling', 'painting', 'windows-doors', 'kitchens', 'bathrooms', 'flooring', 'siding', 'basements']::text[], null, 'medium', 'RRP in one line', 'Paid renovation in pre-1978 homes or child-occupied facilities: certified firm + certified renovator, pamphlet within 60 days before work, signs, containment, cleaning verification (40 CFR 745 Subpart E).', null, null, null, md5('academykb:section:cfr:745.85(a)')::uuid, '40 CFR 745.85(a)', 'regulatory', 'original', 'approved', array['lead-safe-renovation-practice']::text[], 92),
  (md5('academykb:item:dot-age')::uuid, 'dot-age', 'question', 'dot-basics', array['general-contracting', 'excavation', 'concrete', 'landscaping', 'tree-removal', 'demolition', 'asphalt-paving', 'roofing']::text[], null, 'medium', 'Under the federal driver qualification rules for interstate commercial motor vehicles, what is the minimum driver age?', '21', array['18', '25', '21', '16']::text[], 2, null, md5('academykb:section:cfr:391.11')::uuid, '49 CFR 391.11', 'regulatory', 'original', 'approved', array['business-law-practice']::text[], 93),
  (md5('academykb:item:dot-one-license')::uuid, 'dot-one-license', 'question', 'dot-basics', array['general-contracting', 'excavation', 'concrete', 'landscaping', 'tree-removal', 'demolition', 'asphalt-paving', 'roofing']::text[], null, 'medium', 'How many commercial motor vehicle operator''s licenses may a qualified driver hold?', 'One, issued by only one state or jurisdiction', array['One per state they drive in', 'None are needed for construction', 'Up to three', 'One, issued by only one state or jurisdiction']::text[], 3, null, md5('academykb:section:cfr:391.11')::uuid, '49 CFR 391.11', 'regulatory', 'original', 'approved', array['business-law-practice']::text[], 94),
  (md5('academykb:item:dot-combination')::uuid, 'dot-combination', 'question', 'dot-basics', array['general-contracting', 'excavation', 'concrete', 'landscaping', 'tree-removal', 'demolition', 'asphalt-paving', 'roofing']::text[], null, 'hard', 'For a tractor-semitrailer combination, which vehicles need the required periodic inspection?', 'Each vehicle: the tractor and the semitrailer (and any full trailer)', array['Only the tractor', 'Only the trailer', 'Only the heaviest unit', 'Each vehicle: the tractor and the semitrailer (and any full trailer)']::text[], 3, null, md5('academykb:section:cfr:396.17(a)')::uuid, '49 CFR 396.17(a)', 'regulatory', 'original', 'approved', array['business-law-practice']::text[], 95),
  (md5('academykb:item:dot-testing')::uuid, 'dot-testing', 'question', 'dot-basics', array['general-contracting', 'excavation', 'concrete', 'landscaping', 'tree-removal', 'demolition', 'asphalt-paving', 'roofing']::text[], null, 'medium', 'Federal drug and alcohol testing (49 CFR Part 382) applies to employers and drivers subject to what?', 'The commercial driver''s license (CDL) requirements of Part 383', array['Only hazardous materials hauling', 'Only drivers over 65', 'Any pickup truck use', 'The commercial driver''s license (CDL) requirements of Part 383']::text[], 3, null, md5('academykb:section:cfr:382.103')::uuid, '49 CFR 382.103', 'regulatory', 'original', 'approved', array['business-law-practice']::text[], 96),
  (md5('academykb:item:dot-owner-operator')::uuid, 'dot-owner-operator', 'question', 'dot-basics', array['general-contracting', 'excavation', 'concrete', 'landscaping', 'tree-removal', 'demolition', 'asphalt-paving', 'roofing']::text[], null, 'hard', 'An owner-operator who employs only themself as a CDL driver must do what for random testing?', 'Join a random testing program with two or more covered employees in the pool (usually a consortium)', array['Nothing; they are exempt', 'Test themself once a year', 'Only test after accidents', 'Join a random testing program with two or more covered employees in the pool (usually a consortium)']::text[], 3, null, md5('academykb:section:cfr:382.103')::uuid, '49 CFR 382.103', 'regulatory', 'original', 'approved', array['business-law-practice']::text[], 97),
  (md5('academykb:item:dot-not-trade')::uuid, 'dot-not-trade', 'question', 'dot-basics', array['general-contracting', 'excavation', 'concrete', 'landscaping', 'tree-removal', 'demolition', 'asphalt-paving', 'roofing']::text[], null, 'medium', 'Does running a concrete or landscaping business automatically make every truck and driver subject to the same DOT rules?', 'No. Coverage depends on the vehicle''s weight ratings, cargo, passengers and type of commerce, not the trade', array['Yes, every construction truck is covered', 'Only if the business is incorporated', 'Only if the truck is red', 'No. Coverage depends on the vehicle''s weight ratings, cargo, passengers and type of commerce, not the trade']::text[], 3, 'Federal rules cover interstate commerce; states set rules for intrastate operation. Check the vehicle''s GVWR and how it''s used.', null, null, 'concept', 'original', 'approved', array['business-law-practice']::text[], 98),
  (md5('academykb:item:mnp-required')::uuid, 'mnp-required', 'question', 'mn-permits', '{}'::text[], 'MN', 'easy', 'In Minnesota, before constructing, altering, repairing, moving, demolishing or changing the occupancy of a building regulated by the code, what must the owner or agent do?', 'Apply to the building official and obtain the required permit', array['Notify the neighbors', 'Hire a licensed engineer', 'Nothing, if the work costs under $5,000', 'Apply to the building official and obtain the required permit']::text[], 3, null, md5('academykb:section:mn:1300.0120 subp. 1')::uuid, 'Minn. R. 1300.0120, subp. 1', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 99),
  (md5('academykb:item:mnp-shed')::uuid, 'mnp-shed', 'question', 'mn-permits', '{}'::text[], 'MN', 'medium', 'In Minnesota, a one-story detached shed or playhouse is exempt from a building permit up to what floor area?', '200 square feet', array['144 square feet', '400 square feet', '200 square feet', '120 square feet']::text[], 2, 'Local zoning and setback rules can still apply even when no building permit is needed.', md5('academykb:section:mn:1300.0120 subp. 4')::uuid, 'Minn. R. 1300.0120, subp. 4', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 100),
  (md5('academykb:item:mnp-fence')::uuid, 'mnp-fence', 'question', 'mn-permits', '{}'::text[], 'MN', 'medium', 'Under Minnesota''s permit exemptions, fences up to what height don''t need a building permit?', '7 feet', array['6 feet', '8 feet', '7 feet', '4 feet']::text[], 2, null, md5('academykb:section:mn:1300.0120 subp. 4')::uuid, 'Minn. R. 1300.0120, subp. 4', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 101),
  (md5('academykb:item:mnp-retaining')::uuid, 'mnp-retaining', 'question', 'mn-permits', '{}'::text[], 'MN', 'hard', 'In Minnesota, a retaining wall is exempt from a building permit if it is no taller than what (and not supporting a surcharge or impounding certain liquids)?', '4 feet, measured from the bottom of the footing to the top of the wall', array['4 feet above finished grade', '3 feet above grade', '6 feet from the footing', '4 feet, measured from the bottom of the footing to the top of the wall']::text[], 3, null, md5('academykb:section:mn:1300.0120 subp. 4')::uuid, 'Minn. R. 1300.0120, subp. 4', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 102),
  (md5('academykb:item:mnp-deck')::uuid, 'mnp-deck', 'question', 'mn-permits', array['decks']::text[], 'MN', 'medium', 'Which deck is exempt from a Minnesota building permit?', 'A deck not more than 30 inches above grade, not attached to a structure with frost footings, and not part of an accessible route', array['Any deck attached to the house', 'Any deck built by the homeowner', 'Any deck under 200 square feet', 'A deck not more than 30 inches above grade, not attached to a structure with frost footings, and not part of an accessible route']::text[], 3, null, md5('academykb:section:mn:1300.0120 subp. 4')::uuid, 'Minn. R. 1300.0120, subp. 4', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 103),
  (md5('academykb:item:mnp-finish')::uuid, 'mnp-finish', 'question', 'mn-permits', '{}'::text[], 'MN', 'easy', 'Which of these is listed as work exempt from a Minnesota building permit?', 'Painting, tiling, carpeting, cabinets and countertops', array['Removing a load-bearing wall', 'Replacing a furnace', 'Adding a bedroom egress window', 'Painting, tiling, carpeting, cabinets and countertops']::text[], 3, null, md5('academykb:section:mn:1300.0120 subp. 4')::uuid, 'Minn. R. 1300.0120, subp. 4', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 104),
  (md5('academykb:item:mnp-exempt-code')::uuid, 'mnp-exempt-code', 'question', 'mn-permits', '{}'::text[], 'MN', 'medium', 'If work is exempt from a Minnesota building permit, does it still have to meet the code?', 'Yes. Exemptions don''t authorize work that violates the code or other laws', array['No, exempt work has no rules', 'Only for commercial buildings', 'Only if an inspector visits', 'Yes. Exemptions don''t authorize work that violates the code or other laws']::text[], 3, null, md5('academykb:section:mn:1300.0120 subp. 4')::uuid, 'Minn. R. 1300.0120, subp. 4', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 105),
  (md5('academykb:item:mnp-emergency')::uuid, 'mnp-emergency', 'question', 'mn-permits', '{}'::text[], 'MN', 'medium', 'In Minnesota, when equipment replacements or repairs must be done in an emergency, when is the permit application due?', 'Within the next working business day', array['Within 30 days', 'Before any work starts, no exceptions', 'Never for emergencies', 'Within the next working business day']::text[], 3, null, md5('academykb:section:mn:1300.0120 subp. 5')::uuid, 'Minn. R. 1300.0120, subp. 5', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 106),
  (md5('academykb:item:mnp-ordinary-repair')::uuid, 'mnp-ordinary-repair', 'question', 'mn-permits', '{}'::text[], 'MN', 'medium', 'Which work is NOT an ''ordinary repair'' under Minnesota''s rule (so it needs an application to the building official)?', 'Cutting or removing a structural beam or load-bearing support', array['Patching drywall', 'Replacing a cabinet door', 'Repainting a room', 'Cutting or removing a structural beam or load-bearing support']::text[], 3, null, md5('academykb:section:mn:1300.0120 subp. 6')::uuid, 'Minn. R. 1300.0120, subp. 6', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 107),
  (md5('academykb:item:mnp-abandoned')::uuid, 'mnp-abandoned', 'question', 'mn-permits', '{}'::text[], 'MN', 'medium', 'In Minnesota, a permit application not pursued in good faith (and with no permit issued) is considered abandoned after how long?', '180 days after filing', array['90 days after filing', '1 year after filing', '180 days after filing', '30 days after filing']::text[], 2, null, md5('academykb:section:mn:1300.0120 subp. 9')::uuid, 'Minn. R. 1300.0120, subp. 9', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 108),
  (md5('academykb:item:mnp-expires')::uuid, 'mnp-expires', 'question', 'mn-permits', '{}'::text[], 'MN', 'medium', 'A Minnesota building permit expires unless the work is started within how long after the permit is issued?', '180 days', array['90 days', '2 years', '180 days', '60 days']::text[], 2, null, md5('academykb:section:mn:1300.0120 subp. 11')::uuid, 'Minn. R. 1300.0120, subp. 11', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 109),
  (md5('academykb:item:mnp-suspended')::uuid, 'mnp-suspended', 'question', 'mn-permits', '{}'::text[], 'MN', 'medium', 'A Minnesota permit becomes invalid if authorized work is suspended or abandoned for more than how long?', '180 days', array['180 days', '1 year', '90 days', '30 days']::text[], 0, null, md5('academykb:section:mn:1300.0120 subp. 10')::uuid, 'Minn. R. 1300.0120, subp. 10', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 110),
  (md5('academykb:item:mnp-posting')::uuid, 'mnp-posting', 'question', 'mn-permits', '{}'::text[], 'MN', 'medium', 'Where must a Minnesota building permit (or a copy) be kept during the project?', 'On the job site until completion, posted in a conspicuous, accessible place', array['At city hall only', 'With the homeowner''s insurance papers', 'In the contractor''s truck', 'On the job site until completion, posted in a conspicuous, accessible place']::text[], 3, null, md5('academykb:section:mn:1300.0120 subp. 13')::uuid, 'Minn. R. 1300.0120, subp. 13', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 111),
  (md5('academykb:item:mnp-responsible')::uuid, 'mnp-responsible', 'question', 'mn-permits', '{}'::text[], 'MN', 'medium', 'In Minnesota, who is responsible for code compliance for the permitted work?', 'The person, firm or organization that secured the permit', array['The building official', 'The homeowner, always', 'The lumber supplier', 'The person, firm or organization that secured the permit']::text[], 3, null, md5('academykb:section:mn:1300.0120 subp. 14')::uuid, 'Minn. R. 1300.0120, subp. 14', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 112),
  (md5('academykb:item:mnp-annual')::uuid, 'mnp-annual', 'question', 'mn-permits', '{}'::text[], 'MN', 'hard', 'In Minnesota, what may the building official issue instead of separate permits for each alteration to an approved electrical, gas, mechanical or plumbing installation, to an owner who employs qualified tradespeople?', 'An annual permit', array['A blanket variance', 'Nothing; each change needs its own permit', 'A verbal approval', 'An annual permit']::text[], 3, null, md5('academykb:section:mn:1300.0120 subp. 2')::uuid, 'Minn. R. 1300.0120, subp. 2', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 113),
  (md5('academykb:item:mnp-rejection')::uuid, 'mnp-rejection', 'question', 'mn-permits', '{}'::text[], 'MN', 'medium', 'If a Minnesota building official rejects a permit application, what must they do?', 'Document the reasons; the applicant may request them in writing', array['Refund double the fee', 'Issue the permit anyway after 30 days', 'Nothing; no reason is required', 'Document the reasons; the applicant may request them in writing']::text[], 3, null, md5('academykb:section:mn:1300.0120 subp. 8')::uuid, 'Minn. R. 1300.0120, subp. 8', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 114),
  (md5('academykb:item:mnp-card-180')::uuid, 'mnp-card-180', 'flashcard', 'mn-permits', '{}'::text[], 'MN', 'medium', 'Minnesota permit 180-day rules', 'Application abandoned 180 days after filing; permit expires if work doesn''t start within 180 days; invalid if work stops for more than 180 days (Minn. R. 1300.0120).', null, null, null, md5('academykb:section:mn:1300.0120 subp. 11')::uuid, 'Minn. R. 1300.0120, subp. 11', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 115),
  (md5('academykb:item:mnp-card-exempt')::uuid, 'mnp-card-exempt', 'flashcard', 'mn-permits', '{}'::text[], 'MN', 'medium', 'Minnesota: common permit exemptions', 'Sheds ≤200 sq ft, fences ≤7 ft, retaining walls ≤4 ft, low freestanding decks ≤30 in, finish work. Still must meet code and zoning (Minn. R. 1300.0120, subp. 4).', null, null, null, md5('academykb:section:mn:1300.0120 subp. 4')::uuid, 'Minn. R. 1300.0120, subp. 4', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'general-contractor-knowledge-practice']::text[], 116),
  (md5('academykb:item:mnr-irc-edition')::uuid, 'mnr-irc-edition', 'question', 'mn-residential-code', '{}'::text[], 'MN', 'easy', 'Which edition of the International Residential Code does Minnesota''s residential code incorporate?', '2018', array['2018', '2024', '2021', '2015']::text[], 0, null, md5('academykb:section:mn:1309.0010 subp. 1')::uuid, 'Minn. R. 1309.0010, subp. 1', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 117),
  (md5('academykb:item:mnr-appendices')::uuid, 'mnr-appendices', 'question', 'mn-residential-code', '{}'::text[], 'MN', 'hard', 'Minnesota deleted all IRC appendices except which two?', 'Appendix K and Appendix Q', array['Appendix A and Appendix B', 'Appendix F and Appendix J', 'None were kept', 'Appendix K and Appendix Q']::text[], 3, null, md5('academykb:section:mn:1309.0010 subp. 1a')::uuid, 'Minn. R. 1309.0010, subp. 1a', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 118),
  (md5('academykb:item:mnr-energy-replaced')::uuid, 'mnr-energy-replaced', 'question', 'mn-residential-code', array['insulation', 'windows-doors', 'hvac']::text[], 'MN', 'medium', 'In Minnesota, IRC Chapter 11 (energy) is replaced by what?', 'Minnesota Rules chapters 1322 and 1323, the Minnesota Energy Code', array['Nothing; there is no energy code', 'Chapter 1346', 'The 2021 IECC as published', 'Minnesota Rules chapters 1322 and 1323, the Minnesota Energy Code']::text[], 3, null, md5('academykb:section:mn:1309.0010 subp. 3')::uuid, 'Minn. R. 1309.0010, subp. 3', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 119)
