  (md5('academykb:item:mnr-plumbing-replaced')::uuid, 'mnr-plumbing-replaced', 'question', 'mn-residential-code', array['plumbing', 'bathrooms', 'kitchens']::text[], 'MN', 'medium', 'In Minnesota, the IRC plumbing chapters (25 to 33) are replaced by which code?', 'The Minnesota Plumbing Code, Minnesota Rules chapter 4714', array['The International Plumbing Code', 'Local ordinances only', 'The Uniform Plumbing Code as published', 'The Minnesota Plumbing Code, Minnesota Rules chapter 4714']::text[], 3, null, md5('academykb:section:mn:1309.0010 subp. 3')::uuid, 'Minn. R. 1309.0010, subp. 3', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 120),
  (md5('academykb:item:mnr-mechanical-replaced')::uuid, 'mnr-mechanical-replaced', 'question', 'mn-residential-code', array['hvac']::text[], 'MN', 'medium', 'In Minnesota, the IRC mechanical chapters (12 to 24) are replaced by which code?', 'The Minnesota Mechanical Code, Minnesota Rules chapter 1346', array['Chapter 1315', 'They are kept as written', 'The Uniform Mechanical Code', 'The Minnesota Mechanical Code, Minnesota Rules chapter 1346']::text[], 3, null, md5('academykb:section:mn:1309.0010 subp. 3')::uuid, 'Minn. R. 1309.0010, subp. 3', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 121),
  (md5('academykb:item:mnr-electrical-replaced')::uuid, 'mnr-electrical-replaced', 'question', 'mn-residential-code', array['electrical']::text[], 'MN', 'hard', 'Minnesota replaces the IRC electrical chapters with the Minnesota Electrical Code, except for which two sections it keeps?', 'R314 Smoke Alarms and R315 Carbon Monoxide Alarms', array['R302 Fire Separation and R303 Light', 'None', 'R311 Egress and R312 Guards', 'R314 Smoke Alarms and R315 Carbon Monoxide Alarms']::text[], 3, null, md5('academykb:section:mn:1309.0010 subp. 3')::uuid, 'Minn. R. 1309.0010, subp. 3', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 122),
  (md5('academykb:item:mnr-nec')::uuid, 'mnr-nec', 'question', 'mn-residential-code', array['electrical']::text[], 'MN', 'medium', 'Which edition of the National Electrical Code does the Minnesota Electrical Code (Minn. R. 1315.0200) adopt?', '2026', array['2023', '2026', '2017', '2020']::text[], 1, null, md5('academykb:section:mn:1315.0200 subp. 1a')::uuid, 'Minn. R. 1315.0200, subp. 1a', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 123),
  (md5('academykb:item:mnr-iecc')::uuid, 'mnr-iecc', 'question', 'mn-residential-code', array['insulation', 'windows-doors', 'hvac']::text[], 'MN', 'medium', 'Minnesota''s residential energy code (Minn. R. 1322) incorporates the residential provisions of which IECC edition?', '2012', array['2021', '2012', '2018', '2009']::text[], 1, null, md5('academykb:section:mn:1322.0010 subp. 1')::uuid, 'Minn. R. 1322.0010, subp. 1', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 124),
  (md5('academykb:item:mnr-imc')::uuid, 'mnr-imc', 'question', 'mn-residential-code', array['hvac']::text[], 'MN', 'medium', 'The Minnesota Mechanical Code incorporates chapters 2 to 15 of which edition of the International Mechanical Code?', '2018', array['2015', '2018', '2024', '2012']::text[], 1, null, md5('academykb:section:mn:1346.0050')::uuid, 'Minn. R. 1346.0050', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 125),
  (md5('academykb:item:mnr-ibc-appendices')::uuid, 'mnr-ibc-appendices', 'question', 'mn-residential-code', array['commercial-remodeling', 'general-contracting']::text[], 'MN', 'hard', 'Which IBC appendices are part of the Minnesota State Building Code (Minn. R. 1305)?', 'None. All IBC appendices are deleted', array['Only Appendix K', 'Appendices C and J', 'All of them', 'None. All IBC appendices are deleted']::text[], 3, null, md5('academykb:section:mn:1305.0011 subp. 1a')::uuid, 'Minn. R. 1305.0011, subp. 1a', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 126),
  (md5('academykb:item:mnr-seismic')::uuid, 'mnr-seismic', 'question', 'mn-residential-code', array['commercial-remodeling', 'general-contracting']::text[], 'MN', 'medium', 'What does Minnesota''s adoption of the IBC do with the IBC''s seismic (earthquake) provisions?', 'Deletes them', array['Keeps them for all buildings', 'Doubles the design loads', 'Keeps them for schools only', 'Deletes them']::text[], 3, null, md5('academykb:section:mn:1305.0011 subp. 4')::uuid, 'Minn. R. 1305.0011, subp. 4', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 127),
  (md5('academykb:item:mnr-stair-scope')::uuid, 'mnr-stair-scope', 'question', 'mn-residential-code', array['decks']::text[], 'MN', 'medium', 'In Minnesota, do the residential stairway rules apply to exterior stairs serving a deck?', 'Yes. They include stairs serving decks, porches and balconies', array['Only stairs over 30 inches tall', 'Only on new homes', 'No, only interior stairs', 'Yes. They include stairs serving decks, porches and balconies']::text[], 3, null, md5('academykb:section:mn:1309.0311 subp. 2')::uuid, 'Minn. R. 1309.0311, subp. 2', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 128),
  (md5('academykb:item:mnr-stair-width')::uuid, 'mnr-stair-width', 'question', 'mn-residential-code', array['decks', 'framing', 'basements']::text[], 'MN', 'easy', 'Under Minnesota''s residential code, what is the minimum clear width of a stairway above the handrail height?', '36 inches', array['36 inches', '42 inches', '32 inches', '30 inches']::text[], 0, null, md5('academykb:section:mn:1309.0311 subp. 2')::uuid, 'Minn. R. 1309.0311, subp. 2', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 129),
  (md5('academykb:item:mnr-handrail-projection')::uuid, 'mnr-handrail-projection', 'question', 'mn-residential-code', array['decks', 'framing']::text[], 'MN', 'hard', 'In Minnesota, how far may a handrail project into the stairway on either side?', 'No more than 4.5 inches', array['No more than 4.5 inches', 'No more than 6 inches', 'Any amount', 'No more than 3 inches']::text[], 0, null, md5('academykb:section:mn:1309.0311 subp. 2')::uuid, 'Minn. R. 1309.0311, subp. 2', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 130),
  (md5('academykb:item:mnr-stair-exceptions')::uuid, 'mnr-stair-exceptions', 'question', 'mn-residential-code', array['framing', 'decks']::text[], 'MN', 'medium', 'Which stairs are excepted from Minnesota''s residential stairway section?', 'Stairs serving only attics or crawl spaces, or only access to plumbing, mechanical or electrical equipment', array['All exterior stairs', 'Stairs with fewer than 4 risers', 'Basement stairs', 'Stairs serving only attics or crawl spaces, or only access to plumbing, mechanical or electrical equipment']::text[], 3, null, md5('academykb:section:mn:1309.0311 subp. 2')::uuid, 'Minn. R. 1309.0311, subp. 2', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 131),
  (md5('academykb:item:mnr-headroom')::uuid, 'mnr-headroom', 'question', 'mn-residential-code', array['framing', 'basements', 'decks']::text[], 'MN', 'easy', 'What is the minimum stairway headroom under Minnesota''s residential code?', '6 feet 8 inches', array['7 feet', '7 feet 6 inches', '6 feet 8 inches', '6 feet 4 inches']::text[], 2, null, md5('academykb:section:mn:1309.0311 subp. 3')::uuid, 'Minn. R. 1309.0311, subp. 3', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 132),
  (md5('academykb:item:mnr-door-landing')::uuid, 'mnr-door-landing', 'question', 'mn-residential-code', array['windows-doors', 'decks']::text[], 'MN', 'hard', 'In Minnesota, exterior doors other than the required egress door need a landing or floor not more than how far below the top of the threshold?', '7-3/4 inches', array['7-3/4 inches', '8-1/4 inches', '12 inches', '4 inches']::text[], 0, null, md5('academykb:section:mn:1309.0311 subp. 1')::uuid, 'Minn. R. 1309.0311, subp. 1', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 133),
  (md5('academykb:item:mnr-guard-height')::uuid, 'mnr-guard-height', 'question', 'mn-residential-code', array['decks', 'framing']::text[], 'MN', 'easy', 'Under Minnesota''s residential code, guards are required along open sides of floors, stairs, ramps and landings more than how high above the floor or grade below?', '30 inches', array['30 inches', '48 inches', '36 inches', '24 inches']::text[], 0, null, md5('academykb:section:mn:1309.0312 subp. 1')::uuid, 'Minn. R. 1309.0312, subp. 1', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 134),
  (md5('academykb:item:mnr-screen-guard')::uuid, 'mnr-screen-guard', 'question', 'mn-residential-code', array['decks']::text[], 'MN', 'medium', 'Can insect screening on a porch count as a required guard in Minnesota?', 'No', array['Yes', 'Yes, if it is aluminum', 'Yes, below 6 feet', 'No']::text[], 3, null, md5('academykb:section:mn:1309.0312 subp. 1')::uuid, 'Minn. R. 1309.0312, subp. 1', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 135),
  (md5('academykb:item:mnr-window-sill')::uuid, 'mnr-window-sill', 'question', 'mn-residential-code', array['windows-doors']::text[], 'MN', 'medium', 'In Minnesota dwellings, when the opening of an operable window is more than 72 inches above the grade below, the lowest part of the opening must be at least how high above the finished floor (unless an exception applies)?', '36 inches', array['30 inches', '36 inches', '44 inches', '24 inches']::text[], 1, null, md5('academykb:section:mn:1309.0312 subp. 2')::uuid, 'Minn. R. 1309.0312, subp. 2', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 136),
  (md5('academykb:item:mnr-window-sphere')::uuid, 'mnr-window-sphere', 'question', 'mn-residential-code', array['windows-doors']::text[], 'MN', 'hard', 'Within 36 inches of the floor, operable window sections that are more than 72 inches above grade outside may not allow passage of what?', 'A 4-inch diameter sphere', array['A 6-inch diameter sphere', 'A 2-inch diameter sphere', 'A child''s hand', 'A 4-inch diameter sphere']::text[], 3, null, md5('academykb:section:mn:1309.0312 subp. 2')::uuid, 'Minn. R. 1309.0312, subp. 2', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 137),
  (md5('academykb:item:mnr-window-replacement')::uuid, 'mnr-window-replacement', 'question', 'mn-residential-code', array['windows-doors']::text[], 'MN', 'medium', 'Does Minnesota''s window fall protection rule (R312.2.1) apply to replacement windows?', 'No. Replacement windows are listed as an exception', array['Only on the second floor', 'Only in bedrooms', 'Yes, always', 'No. Replacement windows are listed as an exception']::text[], 3, null, md5('academykb:section:mn:1309.0312 subp. 2')::uuid, 'Minn. R. 1309.0312, subp. 2', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 138),
  (md5('academykb:item:mnr-frozen-soil')::uuid, 'mnr-frozen-soil', 'question', 'mn-residential-code', array['foundations', 'concrete', 'decks']::text[], 'MN', 'easy', 'May footings bear on frozen soil under Minnesota''s residential code?', 'No', array['Yes, in summer only', 'Yes, for decks', 'Yes, if covered with insulation', 'No']::text[], 3, null, md5('academykb:section:mn:1309.0403 subp. 1')::uuid, 'Minn. R. 1309.0403, subp. 1', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 139),
  (md5('academykb:item:mnr-frost-methods')::uuid, 'mnr-frost-methods', 'question', 'mn-residential-code', array['foundations', 'concrete']::text[], 'MN', 'medium', 'Which is one of the frost protection methods allowed for foundations in Minnesota?', 'Extending below the frost line in Table R301.2(1)', array['Adding calcium chloride to the concrete', 'Using larger anchor bolts', 'Pouring on a gravel bed at any depth', 'Extending below the frost line in Table R301.2(1)']::text[], 3, null, md5('academykb:section:mn:1309.0403 subp. 1')::uuid, 'Minn. R. 1309.0403, subp. 1', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 140),
  (md5('academykb:item:mnr-anchor-spacing')::uuid, 'mnr-anchor-spacing', 'question', 'mn-residential-code', array['foundations', 'framing', 'concrete']::text[], 'MN', 'medium', 'In Minnesota, sill plates must be anchored to the foundation with anchor bolts spaced at most how far on center?', '6 feet', array['8 feet', '10 feet', '6 feet', '4 feet']::text[], 2, null, md5('academykb:section:mn:1309.0403 subp. 2')::uuid, 'Minn. R. 1309.0403, subp. 2', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 141),
  (md5('academykb:item:mnr-anchor-embed')::uuid, 'mnr-anchor-embed', 'question', 'mn-residential-code', array['foundations', 'concrete']::text[], 'MN', 'hard', 'In Minnesota, how far must foundation anchor bolts extend into concrete or grouted masonry cells?', 'At least 7 inches', array['At least 7 inches', 'At least 10 inches', 'At least 12 inches', 'At least 4 inches']::text[], 0, null, md5('academykb:section:mn:1309.0403 subp. 2')::uuid, 'Minn. R. 1309.0403, subp. 2', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 142),
  (md5('academykb:item:mnr-anchor-ends')::uuid, 'mnr-anchor-ends', 'question', 'mn-residential-code', array['foundations', 'framing']::text[], 'MN', 'hard', 'How many anchor bolts does each plate section need in Minnesota, and how close to each end?', 'At least two, with one no more than 12 inches (and not less than 7 bolt diameters) from each end', array['One in the middle', 'Three, evenly spaced', 'One per 10 feet', 'At least two, with one no more than 12 inches (and not less than 7 bolt diameters) from each end']::text[], 3, null, md5('academykb:section:mn:1309.0403 subp. 2')::uuid, 'Minn. R. 1309.0403, subp. 2', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 143),
  (md5('academykb:item:mnr-deck-loads')::uuid, 'mnr-deck-loads', 'question', 'mn-residential-code', array['decks']::text[], 'MN', 'medium', 'Minnesota''s deck footing table (Table R507.3.1 as amended) is based on what live and dead loads?', '40 psf live load and 10 psf dead load', array['50 psf live load and 15 psf dead load', '60 psf live load and 20 psf dead load', '30 psf live load and 10 psf dead load', '40 psf live load and 10 psf dead load']::text[], 3, null, md5('academykb:section:mn:1309.0507 subp. 1')::uuid, 'Minn. R. 1309.0507, subp. 1', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 144),
  (md5('academykb:item:mnr-deck-min-footing')::uuid, 'mnr-deck-min-footing', 'question', 'mn-residential-code', array['decks', 'concrete']::text[], 'MN', 'medium', 'Minnesota''s deck footing table assumes a minimum square footing of what size for a 6x6 post?', '12 inches x 12 inches x 6 inches', array['12 inches x 12 inches x 6 inches', '24 inches x 24 inches x 12 inches', '16 inches x 16 inches x 8 inches', '8 inches x 8 inches x 4 inches']::text[], 0, null, md5('academykb:section:mn:1309.0507 subp. 1')::uuid, 'Minn. R. 1309.0507, subp. 1', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 145),
  (md5('academykb:item:mnr-deck-pier')::uuid, 'mnr-deck-pier', 'question', 'mn-residential-code', array['decks', 'masonry']::text[], 'MN', 'hard', 'If a deck is supported on a brick or CMU pier in Minnesota, how far must the footing project beyond the pier on all sides?', 'At least 2 inches', array['At least 2 inches', 'At least 6 inches', 'At least 4 inches', 'At least 1 inch']::text[], 0, null, md5('academykb:section:mn:1309.0507 subp. 1')::uuid, 'Minn. R. 1309.0507, subp. 1', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 146),
  (md5('academykb:item:mnr-ledger-flash')::uuid, 'mnr-ledger-flash', 'question', 'mn-residential-code', array['decks']::text[], 'MN', 'medium', 'Under Minnesota''s deck ledger table, how must ledgers be treated to keep water off the house band joist?', 'Flashed in accordance with Section R703.4', array['Painted', 'Spaced 1/4 inch from the house with no flashing', 'Caulked only', 'Flashed in accordance with Section R703.4']::text[], 3, null, md5('academykb:section:mn:1309.0507 subp. 4')::uuid, 'Minn. R. 1309.0507, subp. 4', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 147),
  (md5('academykb:item:mnr-ledger-lag')::uuid, 'mnr-ledger-lag', 'question', 'mn-residential-code', array['decks']::text[], 'MN', 'hard', 'When lag screws attach a deck ledger to the band joist under Minnesota''s table, how far must the lag screw tip go?', 'Fully beyond the inside face of the band joist', array['1 inch into the band joist', 'Only through the sheathing', 'At least halfway into the band joist', 'Fully beyond the inside face of the band joist']::text[], 3, null, md5('academykb:section:mn:1309.0507 subp. 4')::uuid, 'Minn. R. 1309.0507, subp. 4', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 148),
  (md5('academykb:item:mnr-ledger-spacing')::uuid, 'mnr-ledger-spacing', 'question', 'mn-residential-code', array['decks']::text[], 'MN', 'hard', 'Using Minnesota''s ledger table: 1/2-inch lag screws with 1/2-inch maximum sheathing, joist span 6 feet or less. What on-center fastener spacing does the table give?', '30 inches', array['30 inches', '36 inches', '23 inches', '16 inches']::text[], 0, 'Read the row for the fastener type, then the column for the joist span. Longer joist spans need closer spacing.', md5('academykb:section:mn:1309.0507 subp. 4')::uuid, 'Minn. R. 1309.0507, subp. 4', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 149),
  (md5('academykb:item:mnr-wrb-laps')::uuid, 'mnr-wrb-laps', 'question', 'mn-residential-code', array['siding', 'exterior-remodeling']::text[], 'MN', 'medium', 'In Minnesota, No. 15 asphalt felt water-resistive barrier is applied horizontally with the upper layer lapped over the lower layer by at least how much?', '2 inches', array['4 inches', '6 inches', '2 inches', '1 inch']::text[], 2, null, md5('academykb:section:mn:1309.0703 subp. 2a')::uuid, 'Minn. R. 1309.0703, subp. 2a', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 150),
  (md5('academykb:item:mnr-wrb-joints')::uuid, 'mnr-wrb-joints', 'question', 'mn-residential-code', array['siding', 'exterior-remodeling']::text[], 'MN', 'medium', 'Where joints occur in No. 15 felt water-resistive barrier in Minnesota, how much must the felt lap?', 'At least 6 inches', array['At least 4 inches', 'At least 12 inches', 'At least 6 inches', 'At least 2 inches']::text[], 2, null, md5('academykb:section:mn:1309.0703 subp. 2a')::uuid, 'Minn. R. 1309.0703, subp. 2a', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 151),
  (md5('academykb:item:mnr-wrb-flashing')::uuid, 'mnr-wrb-flashing', 'question', 'mn-residential-code', array['siding', 'windows-doors']::text[], 'MN', 'medium', 'In Minnesota, how much must the water-resistive barrier overlap the required flashings?', 'At least 2 inches', array['At least 6 inches', 'It should not overlap flashing', 'At least 2 inches', 'At least 1 inch']::text[], 2, null, md5('academykb:section:mn:1309.0703 subp. 2a')::uuid, 'Minn. R. 1309.0703, subp. 2a', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 152),
  (md5('academykb:item:mnr-flash-shingle')::uuid, 'mnr-flash-shingle', 'question', 'mn-residential-code', array['siding', 'windows-doors']::text[], 'MN', 'medium', 'How must wall flashing be applied under Minnesota''s amended R703.4?', 'Shingle-fashion, so water can''t get into the wall cavity', array['Reverse-lapped behind the barrier', 'Caulked with no laps', 'Only at the top of the wall', 'Shingle-fashion, so water can''t get into the wall cavity']::text[], 3, null, md5('academykb:section:mn:1309.0703 subp. 2b')::uuid, 'Minn. R. 1309.0703, subp. 2b', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 153),
  (md5('academykb:item:mnr-flash-windows')::uuid, 'mnr-flash-windows', 'question', 'mn-residential-code', array['windows-doors', 'siding']::text[], 'MN', 'medium', 'Under Minnesota''s flashing rule, where must flashing be installed at exterior window and door openings?', 'At the head and sides', array['At the sill only', 'Nowhere if the window has a nailing fin', 'At the head only', 'At the head and sides']::text[], 3, null, md5('academykb:section:mn:1309.0703 subp. 2b')::uuid, 'Minn. R. 1309.0703, subp. 2b', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 154),
  (md5('academykb:item:mnr-kickout-length')::uuid, 'mnr-kickout-length', 'question', 'mn-residential-code', array['roofing', 'siding']::text[], 'MN', 'medium', 'In Minnesota, what is the minimum length of the kick-out flashing on the roof where an eave meets a sidewall?', '2-1/2 inches', array['4 inches', '6 inches', '2-1/2 inches', '1 inch']::text[], 2, null, md5('academykb:section:mn:1309.0903')::uuid, 'Minn. R. 1309.0903', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 155),
  (md5('academykb:item:mnr-kickout-reroof')::uuid, 'mnr-kickout-reroof', 'question', 'mn-residential-code', array['roofing', 'siding']::text[], 'MN', 'medium', 'In Minnesota, is kick-out flashing required when you only re-roof an existing house (no re-siding)?', 'No. It''s required when re-siding, but not for re-roofing only', array['Only on two-story homes', 'Only with metal roofs', 'Yes, always', 'No. It''s required when re-siding, but not for re-roofing only']::text[], 3, null, md5('academykb:section:mn:1309.0903')::uuid, 'Minn. R. 1309.0903', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 156),
  (md5('academykb:item:mnr-flash-metal')::uuid, 'mnr-flash-metal', 'question', 'mn-residential-code', array['roofing']::text[], 'MN', 'hard', 'When roof flashing is metal in Minnesota, what minimum thickness is required?', '0.019 inch (No. 26 galvanized sheet)', array['0.032 inch', '1/8 inch', '0.019 inch (No. 26 galvanized sheet)', '0.010 inch']::text[], 2, null, md5('academykb:section:mn:1309.0903')::uuid, 'Minn. R. 1309.0903', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 157),
  (md5('academykb:item:mnr-shingle-deck')::uuid, 'mnr-shingle-deck', 'question', 'mn-residential-code', array['roofing']::text[], 'MN', 'medium', 'Under Minnesota''s amended R905.2.1, asphalt shingles must be fastened to what?', 'Solidly sheathed decks or 1-inch nominal wood boards', array['Spaced 1x4 strapping', 'Foam board only', 'Directly to rafters', 'Solidly sheathed decks or 1-inch nominal wood boards']::text[], 3, null, md5('academykb:section:mn:1309.0905 subp. 1')::uuid, 'Minn. R. 1309.0905, subp. 1', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 158),
  (md5('academykb:item:mnr-plaster-coats')::uuid, 'mnr-plaster-coats', 'question', 'mn-residential-code', array['siding', 'masonry']::text[], 'MN', 'medium', 'In Minnesota, how many coats of portland cement plaster are required over metal or wire lath?', 'Not less than three', array['Not less than two', 'Four', 'Not less than three', 'One']::text[], 2, null, md5('academykb:section:mn:1309.0703 subp. 3')::uuid, 'Minn. R. 1309.0703, subp. 3', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 159),
  (md5('academykb:item:mnr-card-stairs')::uuid, 'mnr-card-stairs', 'flashcard', 'mn-residential-code', '{}'::text[], 'MN', 'medium', 'Minnesota stair basics (Minn. R. 1309.0311)', '36 in clear width, handrails project ≤4.5 in, 6 ft 8 in headroom, and the rules cover deck and porch stairs.', null, null, null, md5('academykb:section:mn:1309.0311 subp. 2')::uuid, 'Minn. R. 1309.0311, subp. 2', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 160),
  (md5('academykb:item:mnr-card-guards')::uuid, 'mnr-card-guards', 'flashcard', 'mn-residential-code', '{}'::text[], 'MN', 'medium', 'Minnesota guards (Minn. R. 1309.0312)', 'Required where open sides are more than 30 inches above the floor or grade below. Insect screening is not a guard.', null, null, null, md5('academykb:section:mn:1309.0312 subp. 1')::uuid, 'Minn. R. 1309.0312, subp. 1', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 161),
  (md5('academykb:item:mnr-card-anchors')::uuid, 'mnr-card-anchors', 'flashcard', 'mn-residential-code', '{}'::text[], 'MN', 'medium', 'Minnesota sill anchor bolts (Minn. R. 1309.0403)', '1/2-inch bolts, max 6 ft on center, at least 7 in into concrete, two per plate section, one within 12 in of each end.', null, null, null, md5('academykb:section:mn:1309.0403 subp. 2')::uuid, 'Minn. R. 1309.0403, subp. 2', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 162),
  (md5('academykb:item:mnr-card-kickout')::uuid, 'mnr-card-kickout', 'flashcard', 'mn-residential-code', '{}'::text[], 'MN', 'medium', 'Minnesota kick-out flashing (Minn. R. 1309.0903)', 'At least 2-1/2 in long where an eave meets a sidewall. Required when re-siding; not when only re-roofing.', null, null, null, md5('academykb:section:mn:1309.0903')::uuid, 'Minn. R. 1309.0903', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 163),
  (md5('academykb:item:mnr-card-editions')::uuid, 'mnr-card-editions', 'flashcard', 'mn-residential-code', '{}'::text[], 'MN', 'medium', 'Minnesota code editions', '2018 IRC/IBC/IMC, 2012 IECC residential provisions, 2026 NEC (Minn. R. 1309, 1305, 1346, 1322, 1315).', null, null, null, md5('academykb:section:mn:1309.0010 subp. 1')::uuid, 'Minn. R. 1309.0010, subp. 1', 'regulatory', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 164),
  (md5('academykb:item:nav-model-code')::uuid, 'nav-model-code', 'question', 'codebook-navigation', '{}'::text[], null, 'easy', 'What is a model code, such as the IRC or the NEC?', 'A code written by a private organization that becomes enforceable only where a state or local government adopts it', array['A federal law that applies everywhere', 'A builder''s own construction standards', 'A sample code used only in schools', 'A code written by a private organization that becomes enforceable only where a state or local government adopts it']::text[], 3, 'States and cities adopt a specific edition, often with amendments. Until adopted, a model code is not law there.', null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 165),
  (md5('academykb:item:nav-irc-scope')::uuid, 'nav-irc-scope', 'question', 'codebook-navigation', '{}'::text[], null, 'easy', 'Which model code is written for one- and two-family dwellings and townhouses up to three stories?', 'International Residential Code (IRC)', array['International Fire Code (IFC)', 'National Electrical Code (NEC)', 'International Building Code (IBC)', 'International Residential Code (IRC)']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 166),
  (md5('academykb:item:nav-ibc-scope')::uuid, 'nav-ibc-scope', 'question', 'codebook-navigation', '{}'::text[], null, 'easy', 'Which model code generally covers commercial and other non-residential buildings?', 'International Building Code (IBC)', array['International Residential Code (IRC)', 'International Energy Conservation Code (IECC)', 'Uniform Plumbing Code (UPC)', 'International Building Code (IBC)']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 167),
  (md5('academykb:item:nav-ahj')::uuid, 'nav-ahj', 'question', 'codebook-navigation', '{}'::text[], null, 'easy', 'What does AHJ stand for?', 'Authority having jurisdiction', array['Approved home jobsite', 'American housing journal', 'Accredited hazard judge', 'Authority having jurisdiction']::text[], 3, 'The AHJ is the office that enforces the code for your project, usually the city or county building department.', null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 168),
  (md5('academykb:item:nav-amendments')::uuid, 'nav-amendments', 'question', 'codebook-navigation', '{}'::text[], null, 'medium', 'A state adopts the 2018 IRC ''with amendments.'' What does that mean for you?', 'Some IRC sections are changed, added or deleted by the state; check the amendments before relying on the model code text', array['The IRC is optional', 'Only the commercial code applies', 'The state uses the 2021 IRC instead', 'Some IRC sections are changed, added or deleted by the state; check the amendments before relying on the model code text']::text[], 3, 'Minnesota, for example, amends IRC stair, guard, footing, deck and flashing sections in Minnesota Rules chapter 1309.', null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 169),
  (md5('academykb:item:nav-edition-check')::uuid, 'nav-edition-check', 'question', 'codebook-navigation', '{}'::text[], null, 'medium', 'You find a requirement in the newest IRC. What should you confirm before using it on a job?', 'Which edition your state and local jurisdiction actually enforce, and any amendments', array['Nothing; the newest edition always applies', 'Whether the section has a figure', 'Only the price of the book', 'Which edition your state and local jurisdiction actually enforce, and any amendments']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 170),
  (md5('academykb:item:nav-deck-stairs')::uuid, 'nav-deck-stairs', 'question', 'codebook-navigation', '{}'::text[], null, 'medium', 'You need the permitted riser height for deck stairs. What''s the best first step?', 'Identify the residential code (IRC) and its stairway section, then check your state''s amendments and the local AHJ', array['Ask the lumber yard', 'Use whatever the last job used', 'Search the OSHA construction standards', 'Identify the residential code (IRC) and its stairway section, then check your state''s amendments and the local AHJ']::text[], 3, 'Stairway rules are in IRC Section R311.7. Minnesota amends parts of it in Minn. R. 1309.0311.', null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 171),
  (md5('academykb:item:nav-r-prefix')::uuid, 'nav-r-prefix', 'question', 'codebook-navigation', '{}'::text[], null, 'medium', 'In the IRC, what does the letter prefix on a section number like R311.7 or P2904 tell you?', 'Which part of the IRC it''s in (R building, M mechanical, P plumbing, E electrical, N energy)', array['The year it was added', 'The page number', 'Whether it is required or optional', 'Which part of the IRC it''s in (R building, M mechanical, P plumbing, E electrical, N energy)']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 172),
  (md5('academykb:item:nav-exceptions')::uuid, 'nav-exceptions', 'question', 'codebook-navigation', '{}'::text[], null, 'medium', 'A code section lists a rule followed by ''Exceptions.'' How should you read it?', 'The exceptions modify the rule; read them before deciding the rule applies to your situation', array['Exceptions are optional suggestions', 'Ignore them unless an inspector mentions them', 'Exceptions apply only to commercial work', 'The exceptions modify the rule; read them before deciding the rule applies to your situation']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 173),
  (md5('academykb:item:nav-footnotes')::uuid, 'nav-footnotes', 'question', 'codebook-navigation', '{}'::text[], null, 'medium', 'Why should you read the footnotes on a code table?', 'Footnotes set conditions such as design loads or limits that change how the table applies', array['They only list the publisher''s copyright', 'They are historical notes with no effect', 'They apply only to metric users', 'Footnotes set conditions such as design loads or limits that change how the table applies']::text[], 3, 'Minnesota''s deck footing table, for example, assumes 40 psf live load and 10 psf dead load in its footnotes.', null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 174),
  (md5('academykb:item:nav-cfr')::uuid, 'nav-cfr', 'question', 'codebook-navigation', '{}'::text[], null, 'medium', 'What does the citation ''29 CFR 1926.501'' refer to?', 'Title 29 of the Code of Federal Regulations, Part 1926 (OSHA construction), section 501', array['The 1926 edition of a building code', 'A Minnesota statute', 'An ICC code chapter', 'Title 29 of the Code of Federal Regulations, Part 1926 (OSHA construction), section 501']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 175),
  (md5('academykb:item:nav-incorporated')::uuid, 'nav-incorporated', 'question', 'codebook-navigation', '{}'::text[], null, 'medium', 'What happens when a code ''incorporates by reference'' a standard such as ASTM or ANSI?', 'That standard (or the referenced part) becomes part of the requirement', array['It is listed for information only', 'It applies only to manufacturers', 'It replaces the whole code', 'That standard (or the referenced part) becomes part of the requirement']::text[], 3, 'For example, OSHA''s hard hat rule refers to ANSI Z89.1 helmet specifications.', null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 176),
  (md5('academykb:item:nav-effective')::uuid, 'nav-effective', 'question', 'codebook-navigation', '{}'::text[], null, 'medium', 'What is a code''s effective date?', 'The date the adopted code becomes enforceable for new permits or work', array['The date the model code was printed', 'The date of the last inspection', 'The date your license expires', 'The date the adopted code becomes enforceable for new permits or work']::text[], 3, 'Some states allow projects already in plan review to finish under the older edition. Check the adoption rule.', null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 177),
  (md5('academykb:item:nav-icc-cycle')::uuid, 'nav-icc-cycle', 'question', 'codebook-navigation', '{}'::text[], null, 'medium', 'How often does the International Code Council publish new editions of its model codes?', 'Every three years', array['Every ten years', 'Only when Congress requires it', 'Every three years', 'Every year']::text[], 2, 'That''s why you see 2018, 2021 and 2024 editions. States adopt new editions on their own schedules.', null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 178),
  (md5('academykb:item:nav-local')::uuid, 'nav-local', 'question', 'codebook-navigation', '{}'::text[], null, 'medium', 'Two neighboring cities in the same state enforce slightly different deck rules. How can that happen?', 'Where state law allows, a city or county can adopt local amendments or optional appendices', array['One city must be breaking the law', 'It can''t; codes are identical nationwide', 'Building codes are set by the lumber yard', 'Where state law allows, a city or county can adopt local amendments or optional appendices']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 179)
insert into public.academy_kb_items (id, key, kind, deck, trades, state_code, difficulty, prompt, answer, options, correct, explanation, section_id, citation, basis, origin, status, exam_tags, sort_order) values
  (md5('academykb:item:nav-competent')::uuid, 'nav-competent', 'question', 'codebook-navigation', '{}'::text[], null, 'medium', 'Under OSHA, what is a ''competent person''?', 'Someone able to identify existing and predictable hazards who is authorized to take prompt corrective action', array['Anyone with an OSHA 10 card', 'The most senior employee', 'A licensed engineer', 'Someone able to identify existing and predictable hazards who is authorized to take prompt corrective action']::text[], 3, 'Defined at 29 CFR 1926.32(f). Many OSHA rules require a competent person for inspections and supervision.', null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 180),
  (md5('academykb:item:nav-qualified')::uuid, 'nav-qualified', 'question', 'codebook-navigation', '{}'::text[], null, 'medium', 'How does OSHA''s ''qualified person'' differ from a ''competent person''?', 'A qualified person has a degree, certificate, professional standing or extensive knowledge to solve problems in the subject', array['They are the same thing', 'A qualified person is the newest employee', 'A qualified person is always an OSHA inspector', 'A qualified person has a degree, certificate, professional standing or extensive knowledge to solve problems in the subject']::text[], 3, 'Defined at 29 CFR 1926.32(m).', null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 181),
  (md5('academykb:item:nav-open-book')::uuid, 'nav-open-book', 'question', 'codebook-navigation', '{}'::text[], null, 'medium', 'For an open-book code exam, what''s the most useful preparation?', 'Practice finding sections quickly with the index and table of contents, and tab the books if the exam rules allow', array['Memorize every page number', 'Bring a different edition', 'Highlight every sentence', 'Practice finding sections quickly with the index and table of contents, and tab the books if the exam rules allow']::text[], 3, 'Each exam provider sets its own rules for tabs and notes. Check the candidate bulletin.', null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 182),
  (md5('academykb:item:nav-card-steps')::uuid, 'nav-card-steps', 'flashcard', 'codebook-navigation', '{}'::text[], null, 'medium', 'Five steps to confirm a code requirement', '1) Code family (IRC, IBC, NEC…) 2) Edition your state enforces 3) The section and its exceptions 4) State and local amendments 5) Confirm with the AHJ.', null, null, null, null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 183),
  (md5('academykb:item:nav-card-ahj')::uuid, 'nav-card-ahj', 'flashcard', 'codebook-navigation', '{}'::text[], null, 'medium', 'AHJ (term)', 'Authority having jurisdiction: the office that enforces the code for your project, usually the city or county building department.', null, null, null, null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 184),
  (md5('academykb:item:nav-card-model')::uuid, 'nav-card-model', 'flashcard', 'codebook-navigation', '{}'::text[], null, 'medium', 'Model code', 'A code written by an organization like ICC or NFPA. It''s only law where a state or city adopts a specific edition.', null, null, null, null, null, 'concept', 'original', 'approved', array['minnesota-residential-practice', 'codebook-navigation-practice', 'general-contractor-knowledge-practice']::text[], 185),
  (md5('academykb:item:tm-gfci')::uuid, 'tm-gfci', 'question', 'construction-terms', array['electrical']::text[], null, 'easy', 'What does a GFCI protect against?', 'Shock, by cutting power when current leaks to ground (a ground fault)', array['Overloaded circuits only', 'Lightning strikes', 'Low voltage', 'Shock, by cutting power when current leaks to ground (a ground fault)']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 186),
  (md5('academykb:item:tm-afci')::uuid, 'tm-afci', 'question', 'construction-terms', array['electrical']::text[], null, 'medium', 'What is an AFCI designed to detect?', 'Dangerous arcing in wiring that can start fires', array['Water leaks', 'Carbon monoxide', 'Ground faults only', 'Dangerous arcing in wiring that can start fires']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 187),
  (md5('academykb:item:tm-branch-circuit')::uuid, 'tm-branch-circuit', 'question', 'construction-terms', array['electrical']::text[], null, 'medium', 'What is a branch circuit?', 'The wiring between the final overcurrent device (breaker or fuse) and the outlets it serves', array['The grounding electrode', 'A circuit for tree lighting', 'The utility''s service drop', 'The wiring between the final overcurrent device (breaker or fuse) and the outlets it serves']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 188),
  (md5('academykb:item:tm-ampacity')::uuid, 'tm-ampacity', 'question', 'construction-terms', array['electrical']::text[], null, 'medium', 'What does ampacity mean?', 'The current a conductor can carry continuously without exceeding its temperature rating', array['The voltage of a circuit', 'The size of the panel', 'The length of a wire run', 'The current a conductor can carry continuously without exceeding its temperature rating']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 189),
  (md5('academykb:item:tm-trap')::uuid, 'tm-trap', 'question', 'construction-terms', array['plumbing']::text[], null, 'easy', 'What does a plumbing trap do?', 'Holds a water seal that keeps sewer gas out of the building', array['Filters drinking water', 'Increases water pressure', 'Stores hot water', 'Holds a water seal that keeps sewer gas out of the building']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 190),
  (md5('academykb:item:tm-vent')::uuid, 'tm-vent', 'question', 'construction-terms', array['plumbing']::text[], null, 'medium', 'Why do drain systems need vents?', 'To let air in so drains flow freely and trap seals aren''t siphoned', array['To cool the pipes', 'To add pressure', 'To release hot water', 'To let air in so drains flow freely and trap seals aren''t siphoned']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 191),
  (md5('academykb:item:tm-dwv')::uuid, 'tm-dwv', 'question', 'construction-terms', array['plumbing']::text[], null, 'medium', 'What does DWV stand for in plumbing?', 'Drain, waste and vent', array['Direct water ventilation', 'Double wall vent', 'Domestic water valve', 'Drain, waste and vent']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 192),
  (md5('academykb:item:tm-backflow')::uuid, 'tm-backflow', 'question', 'construction-terms', array['plumbing']::text[], null, 'medium', 'What does a backflow preventer do?', 'Stops contaminated water from flowing back into the potable water supply', array['Lowers water pressure', 'Drains a water heater', 'Heats water', 'Stops contaminated water from flowing back into the potable water supply']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 193),
  (md5('academykb:item:tm-square')::uuid, 'tm-square', 'question', 'construction-terms', array['roofing']::text[], null, 'easy', 'In roofing, what is a ''square''?', '100 square feet of roof area', array['One bundle of shingles', 'One hour of labor', 'A 10-foot by 10-foot sheet of plywood', '100 square feet of roof area']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 194),
  (md5('academykb:item:tm-pitch')::uuid, 'tm-pitch', 'question', 'construction-terms', array['roofing']::text[], null, 'medium', 'What does a 6:12 roof pitch mean?', 'The roof rises 6 inches for every 12 inches of horizontal run', array['Six layers of shingles', 'A 6-degree slope', 'The roof is 6 feet tall and 12 feet wide', 'The roof rises 6 inches for every 12 inches of horizontal run']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 195),
  (md5('academykb:item:tm-drip-edge')::uuid, 'tm-drip-edge', 'question', 'construction-terms', array['roofing']::text[], null, 'medium', 'What is drip edge?', 'Metal flashing at roof edges that directs water away from the fascia and decking', array['A gutter guard', 'A type of shingle', 'A ridge vent', 'Metal flashing at roof edges that directs water away from the fascia and decking']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 196),
  (md5('academykb:item:tm-ton')::uuid, 'tm-ton', 'question', 'construction-terms', array['hvac']::text[], null, 'medium', 'In HVAC, one ton of cooling equals how many BTU per hour?', '12,000 BTU per hour', array['12,000 BTU per hour', '100,000 BTU per hour', '24,000 BTU per hour', '1,000 BTU per hour']::text[], 0, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 197),
  (md5('academykb:item:tm-btu')::uuid, 'tm-btu', 'question', 'construction-terms', array['hvac']::text[], null, 'medium', 'What is a BTU?', 'The heat needed to raise one pound of water by one degree Fahrenheit', array['A unit of air pressure', 'A type of refrigerant', 'A measure of duct size', 'The heat needed to raise one pound of water by one degree Fahrenheit']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 198),
  (md5('academykb:item:tm-manual-j')::uuid, 'tm-manual-j', 'question', 'construction-terms', array['hvac']::text[], null, 'medium', 'What is a Manual J calculation used for?', 'Calculating a home''s heating and cooling loads to size equipment', array['Estimating paint', 'Sizing roof rafters', 'Designing electrical panels', 'Calculating a home''s heating and cooling loads to size equipment']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 199),
  (md5('academykb:item:tm-ledger')::uuid, 'tm-ledger', 'question', 'construction-terms', array['decks']::text[], null, 'easy', 'On a deck, what is the ledger?', 'The board fastened to the house that supports one end of the deck joists', array['The first stair tread', 'The concrete footing', 'The top rail of the guard', 'The board fastened to the house that supports one end of the deck joists']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 200),
  (md5('academykb:item:tm-frost-line')::uuid, 'tm-frost-line', 'question', 'construction-terms', array['decks', 'foundations', 'concrete']::text[], null, 'medium', 'What is the frost line?', 'The depth to which ground is expected to freeze; footings go below it unless frost-protected another way', array['The top of the foundation wall', 'Ice on a window', 'The coldest day of the year', 'The depth to which ground is expected to freeze; footings go below it unless frost-protected another way']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 201),
  (md5('academykb:item:tm-psi')::uuid, 'tm-psi', 'question', 'construction-terms', array['concrete']::text[], null, 'medium', 'When concrete is specified as ''3,000 psi,'' what does that describe?', 'Its compressive strength, usually measured at 28 days', array['The pump pressure', 'The weight per cubic yard', 'How fast it sets', 'Its compressive strength, usually measured at 28 days']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 202),
  (md5('academykb:item:tm-slump')::uuid, 'tm-slump', 'question', 'construction-terms', array['concrete']::text[], null, 'medium', 'What does a concrete slump test measure?', 'The consistency (workability) of fresh concrete', array['Final strength', 'Rebar size', 'Air temperature', 'The consistency (workability) of fresh concrete']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 203),
  (md5('academykb:item:tm-control-joint')::uuid, 'tm-control-joint', 'question', 'construction-terms', array['concrete']::text[], null, 'medium', 'Why are control joints cut or formed in concrete slabs?', 'To make cracking happen in straight, planned lines', array['To drain water', 'To speed curing', 'To hold rebar', 'To make cracking happen in straight, planned lines']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 204),
  (md5('academykb:item:tm-header')::uuid, 'tm-header', 'question', 'construction-terms', array['framing']::text[], null, 'easy', 'In framing, what is a header?', 'A beam over a door or window opening that carries the load above it', array['The bottom plate of a wall', 'A roof vent', 'A stair stringer', 'A beam over a door or window opening that carries the load above it']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 205),
  (md5('academykb:item:tm-jack-stud')::uuid, 'tm-jack-stud', 'question', 'construction-terms', array['framing']::text[], null, 'medium', 'What is a jack (trimmer) stud?', 'A shortened stud that supports the end of a header', array['A stud under a window sill only', 'A metal stud', 'A stud used to lift a house', 'A shortened stud that supports the end of a header']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 206),
  (md5('academykb:item:tm-oc')::uuid, 'tm-oc', 'question', 'construction-terms', array['framing']::text[], null, 'medium', 'What does ''16 inches o.c.'' mean on a framing plan?', 'Framing members spaced 16 inches on center (center to center)', array['16-inch overhang clearance', '16 ounces of construction adhesive', '16 inches of open cavity', 'Framing members spaced 16 inches on center (center to center)']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 207),
  (md5('academykb:item:tm-sill-plate')::uuid, 'tm-sill-plate', 'question', 'construction-terms', array['framing', 'foundations']::text[], null, 'medium', 'What is a sill plate?', 'The bottom framing member anchored to the foundation', array['A plate on a door strike', 'Roof sheathing', 'A window sill', 'The bottom framing member anchored to the foundation']::text[], 3, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 208),
  (md5('academykb:item:tm-card-square')::uuid, 'tm-card-square', 'flashcard', 'construction-terms', array['roofing']::text[], null, 'medium', 'Roofing square', '100 square feet of roof area.', null, null, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 209),
  (md5('academykb:item:tm-card-ton')::uuid, 'tm-card-ton', 'flashcard', 'construction-terms', array['hvac']::text[], null, 'medium', 'HVAC ton', '12,000 BTU per hour of cooling.', null, null, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 210),
  (md5('academykb:item:tm-card-trap')::uuid, 'tm-card-trap', 'flashcard', 'construction-terms', array['plumbing']::text[], null, 'medium', 'Plumbing trap', 'A bend that holds water to block sewer gas. Vents protect the seal from siphoning.', null, null, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 211),
  (md5('academykb:item:tm-card-gfci')::uuid, 'tm-card-gfci', 'flashcard', 'construction-terms', array['electrical']::text[], null, 'medium', 'GFCI vs AFCI', 'GFCI protects people from shock (ground faults). AFCI protects against fire from arcing.', null, null, null, null, null, 'concept', 'original', 'approved', '{}'::text[], 212),
  (md5('academykb:item:biz-ein')::uuid, 'biz-ein', 'question', 'business-setup', '{}'::text[], null, 'easy', 'What is an EIN?', 'A federal tax ID number for a business, issued free by the IRS', array['A state contractor license number', 'An insurance policy number', 'A building permit number', 'A federal tax ID number for a business, issued free by the IRS']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 213),
  (md5('academykb:item:biz-llc')::uuid, 'biz-llc', 'question', 'business-setup', '{}'::text[], null, 'medium', 'What''s the main reason contractors form an LLC instead of staying a sole proprietor?', 'To separate business liabilities from personal assets (when the business is run properly)', array['To avoid all taxes', 'Because LLCs don''t need licenses', 'Because insurance isn''t needed for an LLC', 'To separate business liabilities from personal assets (when the business is run properly)']::text[], 3, 'An LLC doesn''t replace insurance, and personal guarantees or mixing funds can weaken the protection.', null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 214),
  (md5('academykb:item:biz-bank')::uuid, 'biz-bank', 'question', 'business-setup', '{}'::text[], null, 'easy', 'Why keep a separate business bank account?', 'It keeps records clean for taxes and helps protect the liability separation of an LLC or corporation', array['Banks require it for any checking account', 'It removes the need for bookkeeping', 'It lowers your income tax rate', 'It keeps records clean for taxes and helps protect the liability separation of an LLC or corporation']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 215),
  (md5('academykb:item:biz-markup-margin')::uuid, 'biz-markup-margin', 'question', 'business-setup', '{}'::text[], null, 'medium', 'A job costs $10,000 and you add a 25% markup. What is your gross margin?', '20%', array['25%', '33%', '20%', '15%']::text[], 2, 'Price = $12,500. Profit $2,500 ÷ price $12,500 = 20% margin. Markup is on cost; margin is on price.', null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 216),
  (md5('academykb:item:biz-margin-price')::uuid, 'biz-margin-price', 'question', 'business-setup', '{}'::text[], null, 'hard', 'You want a 30% gross margin on a job that costs $7,000. What price should you charge?', '$10,000', array['$10,000', '$10,500', '$9,333', '$9,100']::text[], 0, 'Price = cost ÷ (1 − margin) = $7,000 ÷ 0.70 = $10,000.', null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 217),
  (md5('academykb:item:biz-overhead')::uuid, 'biz-overhead', 'question', 'business-setup', '{}'::text[], null, 'medium', 'Which is an overhead cost rather than a direct job cost?', 'Office rent and your accounting software', array['Lumber for the job', 'A dumpster for the job', 'A subcontractor on the job', 'Office rent and your accounting software']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 218),
  (md5('academykb:item:biz-change-order')::uuid, 'biz-change-order', 'question', 'business-setup', '{}'::text[], null, 'easy', 'What is a change order?', 'A written, signed change to the contract''s scope, price or schedule', array['A material delivery ticket', 'A payroll correction', 'A building inspection request', 'A written, signed change to the contract''s scope, price or schedule']::text[], 3, 'Get it signed before doing the extra work. Verbal changes are a common cause of payment disputes.', null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 219),
  (md5('academykb:item:biz-retainage')::uuid, 'biz-retainage', 'question', 'business-setup', '{}'::text[], null, 'medium', 'What is retainage?', 'A percentage of each payment held back until the project is complete', array['A deposit you keep if the client cancels', 'A tool rental fee', 'Interest on late payments', 'A percentage of each payment held back until the project is complete']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 220),
  (md5('academykb:item:biz-lien-waiver')::uuid, 'biz-lien-waiver', 'question', 'business-setup', '{}'::text[], null, 'medium', 'What does a lien waiver do?', 'Confirms payment and gives up lien rights for the amount covered', array['Cancels the contract', 'Extends the warranty', 'Removes the need for a permit', 'Confirms payment and gives up lien rights for the amount covered']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 221),
  (md5('academykb:item:biz-mechanics-lien')::uuid, 'biz-mechanics-lien', 'question', 'business-setup', '{}'::text[], null, 'medium', 'What is a mechanic''s lien?', 'A legal claim against property for unpaid labor or materials, with notice rules and deadlines set by each state', array['A traffic ticket for work trucks', 'A required insurance policy', 'A loan for buying tools', 'A legal claim against property for unpaid labor or materials, with notice rules and deadlines set by each state']::text[], 3, 'Many states require a preliminary notice early in the job to keep lien rights. Check your state''s deadlines.', null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 222),
  (md5('academykb:item:biz-classification')::uuid, 'biz-classification', 'question', 'business-setup', '{}'::text[], null, 'medium', 'What mostly decides whether a worker is an employee or an independent contractor?', 'How much control the business has over how, when and where the work is done, under IRS and state tests', array['Whether they''re paid by check', 'Whether they have their own truck, nothing else', 'Whatever the worker prefers', 'How much control the business has over how, when and where the work is done, under IRS and state tests']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 223),
  (md5('academykb:item:biz-deposit')::uuid, 'biz-deposit', 'question', 'business-setup', '{}'::text[], null, 'medium', 'Before taking a large deposit, what should you check?', 'Whether your state limits deposit amounts or requires specific contract terms for home improvement work', array['Nothing; deposits are always unlimited', 'Only your bank''s fees', 'Only the client''s credit score', 'Whether your state limits deposit amounts or requires specific contract terms for home improvement work']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 224),
  (md5('academykb:item:biz-written-contract')::uuid, 'biz-written-contract', 'question', 'business-setup', '{}'::text[], null, 'easy', 'What should a basic construction contract spell out?', 'Scope, price, payment schedule, timeline, change order process and warranty', array['Only the price', 'Nothing; a handshake is standard', 'Only the start date', 'Scope, price, payment schedule, timeline, change order process and warranty']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 225),
  (md5('academykb:item:biz-card-markup')::uuid, 'biz-card-markup', 'flashcard', 'business-setup', '{}'::text[], null, 'medium', 'Markup vs margin', 'Markup is profit ÷ cost; margin is profit ÷ price. 25% markup = 20% margin. Price for a margin = cost ÷ (1 − margin).', null, null, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 226),
  (md5('academykb:item:biz-card-change')::uuid, 'biz-card-change', 'flashcard', 'business-setup', '{}'::text[], null, 'medium', 'Change order rule of thumb', 'Write it, price it, get it signed before you do the extra work.', null, null, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 227),
  (md5('academykb:item:biz-card-retainage')::uuid, 'biz-card-retainage', 'flashcard', 'business-setup', '{}'::text[], null, 'medium', 'Retainage', 'Money held back from each payment (often 5–10%) until completion. Plan cash flow for it.', null, null, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 228),
  (md5('academykb:item:ins-gl')::uuid, 'ins-gl', 'question', 'insurance-terms', '{}'::text[], null, 'easy', 'What does commercial general liability (GL) insurance mainly cover?', 'Third-party bodily injury and property damage caused by your business', array['Injuries to your own employees', 'Your own truck in an accident', 'Theft of your tools', 'Third-party bodily injury and property damage caused by your business']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 229),
  (md5('academykb:item:ins-wc')::uuid, 'ins-wc', 'question', 'insurance-terms', '{}'::text[], null, 'easy', 'Which coverage pays for your employees'' work-related injuries?', 'Workers'' compensation', array['Inland marine', 'Builder''s risk', 'General liability', 'Workers'' compensation']::text[], 3, 'Most states require workers'' comp once you have employees; rules and exemptions vary by state.', null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 230),
  (md5('academykb:item:ins-inland-marine')::uuid, 'ins-inland-marine', 'question', 'insurance-terms', '{}'::text[], null, 'medium', 'Which coverage protects tools and equipment you carry from job to job?', 'Inland marine (contractor''s equipment) coverage', array['General liability', 'Workers'' compensation', 'Umbrella', 'Inland marine (contractor''s equipment) coverage']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 231),
  (md5('academykb:item:ins-auto')::uuid, 'ins-auto', 'question', 'insurance-terms', '{}'::text[], null, 'medium', 'Does a personal auto policy usually cover a truck used mainly for your contracting business?', 'Often not; business vehicles generally need a commercial auto policy', array['Yes, always', 'Only for passengers', 'Only on weekends', 'Often not; business vehicles generally need a commercial auto policy']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 232),
  (md5('academykb:item:ins-umbrella')::uuid, 'ins-umbrella', 'question', 'insurance-terms', '{}'::text[], null, 'medium', 'What does an umbrella policy do?', 'Adds liability limits above your underlying policies such as GL and auto', array['Covers rain delays', 'Replaces workers'' comp', 'Covers tools only', 'Adds liability limits above your underlying policies such as GL and auto']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 233),
  (md5('academykb:item:ins-builders-risk')::uuid, 'ins-builders-risk', 'question', 'insurance-terms', '{}'::text[], null, 'medium', 'What does builder''s risk insurance cover?', 'The building or project itself while it''s under construction (for example fire or theft of installed materials)', array['Injuries to workers', 'Mistakes in your design work', 'Your office lease', 'The building or project itself while it''s under construction (for example fire or theft of installed materials)']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 234),
  (md5('academykb:item:ins-coi')::uuid, 'ins-coi', 'question', 'insurance-terms', '{}'::text[], null, 'easy', 'What is a certificate of insurance (COI)?', 'A document showing a business''s insurance policies, limits and dates', array['The insurance policy itself', 'A license to work', 'A safety training card', 'A document showing a business''s insurance policies, limits and dates']::text[], 3, 'Ask subcontractors for a current COI before they start work.', null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 235),
  (md5('academykb:item:ins-additional-insured')::uuid, 'ins-additional-insured', 'question', 'insurance-terms', '{}'::text[], null, 'medium', 'A general contractor asks to be named an ''additional insured'' on your policy. What does that mean?', 'Your liability policy extends certain coverage to them for claims arising from your work', array['They can cancel your policy', 'They pay half your premium', 'They get a copy of your bill', 'Your liability policy extends certain coverage to them for claims arising from your work']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 236),
  (md5('academykb:item:ins-bond')::uuid, 'ins-bond', 'question', 'insurance-terms', '{}'::text[], null, 'medium', 'How is a surety bond different from insurance?', 'A bond guarantees your performance or payment to the owner; the surety can seek repayment from you', array['There is no difference', 'A bond covers your tools', 'A bond covers your own injuries', 'A bond guarantees your performance or payment to the owner; the surety can seek repayment from you']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 237),
  (md5('academykb:item:ins-occurrence')::uuid, 'ins-occurrence', 'question', 'insurance-terms', '{}'::text[], null, 'hard', 'What''s the difference between an occurrence policy and a claims-made policy?', 'Occurrence covers incidents during the policy period whenever claimed; claims-made covers claims made while the policy is active', array['They are the same', 'Occurrence only covers fires', 'Claims-made is always cheaper and better', 'Occurrence covers incidents during the policy period whenever claimed; claims-made covers claims made while the policy is active']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 238),
  (md5('academykb:item:ins-card-gl-wc')::uuid, 'ins-card-gl-wc', 'flashcard', 'insurance-terms', '{}'::text[], null, 'medium', 'GL vs workers'' comp', 'GL: injury or damage to others. Workers'' comp: injuries to your own employees.', null, null, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 239)
insert into public.academy_kb_items (id, key, kind, deck, trades, state_code, difficulty, prompt, answer, options, correct, explanation, section_id, citation, basis, origin, status, exam_tags, sort_order) values
  (md5('academykb:item:ins-card-bond')::uuid, 'ins-card-bond', 'flashcard', 'insurance-terms', '{}'::text[], null, 'medium', 'Surety bond', 'A guarantee to the owner that you''ll perform or pay. Not insurance for you; the surety can come back to you for losses.', null, null, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 240),
  (md5('academykb:item:lic-varies')::uuid, 'lic-varies', 'question', 'licensing-basics', '{}'::text[], null, 'easy', 'Does every state license general contractors the same way?', 'No. Some license at the state level, some leave it to cities or counties, and many license only certain trades or job sizes', array['Yes, there is one national license', 'Only federal OSHA licenses contractors', 'No state licenses contractors', 'No. Some license at the state level, some leave it to cities or counties, and many license only certain trades or job sizes']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 241),
  (md5('academykb:item:lic-trades')::uuid, 'lic-trades', 'question', 'licensing-basics', '{}'::text[], null, 'medium', 'Which trades are most commonly licensed separately from general contracting?', 'Electrical and plumbing (often HVAC too)', array['Painting and cleaning', 'Landscaping only', 'None', 'Electrical and plumbing (often HVAC too)']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 242),
  (md5('academykb:item:lic-check')::uuid, 'lic-check', 'question', 'licensing-basics', '{}'::text[], null, 'medium', 'Before bidding work in a new state, where should you confirm licensing requirements?', 'The state''s licensing board, and the local building department for local licenses or registrations', array['A national directory only', 'Your supplier', 'A competitor', 'The state''s licensing board, and the local building department for local licenses or registrations']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 243),
  (md5('academykb:item:lic-epa')::uuid, 'lic-epa', 'question', 'licensing-basics', '{}'::text[], null, 'medium', 'Separate from any state license, which federal certification is needed to do paid renovation that disturbs paint in pre-1978 homes?', 'EPA lead-safe (RRP) firm certification with certified renovators', array['An OSHA 10 card', 'A DOT number', 'No certification is ever needed', 'EPA lead-safe (RRP) firm certification with certified renovators']::text[], 3, null, md5('academykb:section:cfr:745.85(a)')::uuid, '40 CFR 745.85(a)', 'regulatory', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 244),
  (md5('academykb:item:lic-exam')::uuid, 'lic-exam', 'question', 'licensing-basics', '{}'::text[], null, 'medium', 'Are Built2Bid practice exams official licensing exams?', 'No. They''re original practice questions; official exams come from your state''s licensing board or its testing provider', array['Yes, they count toward your license', 'Yes, in Minnesota only', 'Yes, if you score 100%', 'No. They''re original practice questions; official exams come from your state''s licensing board or its testing provider']::text[], 3, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 245),
  (md5('academykb:item:lic-card-check')::uuid, 'lic-card-check', 'flashcard', 'licensing-basics', '{}'::text[], null, 'medium', 'Licensing checklist', 'State board license (if any) · local license or registration · trade licenses · EPA RRP for pre-1978 work · insurance and bond the license requires.', null, null, null, null, null, 'concept', 'original', 'approved', array['business-law-practice', 'general-contractor-knowledge-practice']::text[], 246)
insert into public.academy_kb_exams (slug, title, summary, state_code, license_kind, trades, decks, default_count, minutes, book_policy, official_info_url, status, sort_order) values
  ('construction-safety-practice', 'Construction Safety Practice Exam (OSHA 1926)', 'Original practice questions on federal OSHA construction rules: fall protection, excavation, ladders, scaffolds, PPE, health hazards and injury reporting. Not an official OSHA test or an OSHA 10/30 card.', null, 'safety', '{}'::text[], array['osha-fall-protection', 'osha-excavation', 'osha-ladders-stairs', 'osha-general', 'osha-health-hazards', 'osha-recordkeeping']::text[], 25, 40, 'unverified', 'https://www.ecfr.gov/current/title-29/subtitle-B/chapter-XVII/part-1926', 'published', 0),
  ('lead-safe-renovation-practice', 'Lead-Safe Renovation Practice (EPA RRP)', 'Original practice questions on the EPA Renovation, Repair and Painting Rule and OSHA''s lead standard. Not the EPA certified renovator course or its exam.', null, 'safety', '{}'::text[], array['epa-lead-rrp', 'osha-health-hazards']::text[], 15, 20, 'unverified', 'https://www.ecfr.gov/current/title-40/chapter-I/subchapter-R/part-745', 'published', 1),
  ('minnesota-residential-practice', 'Minnesota Residential Building Practice Exam', 'Original practice questions on Minnesota permits and the Minnesota Residential Code amendments, plus codebook navigation. Not the Minnesota residential contractor licensing exam.', 'MN', 'residential', '{}'::text[], array['mn-permits', 'mn-residential-code', 'codebook-navigation']::text[], 25, 40, 'unverified', 'https://www.revisor.mn.gov/rules/1309/', 'published', 2),
  ('business-law-practice', 'Business and Law Basics Practice Exam', 'Original practice questions on business setup, insurance, licensing basics, injury reporting and commercial vehicles. Business and law exam content differs by state; this is general preparation only.', null, 'business_law', '{}'::text[], array['business-setup', 'insurance-terms', 'licensing-basics', 'osha-recordkeeping', 'dot-basics']::text[], 25, 35, 'unverified', null, 'published', 3),
  ('codebook-navigation-practice', 'Codebook Navigation Practice', 'Practice finding and confirming a requirement: code families, editions, amendments, exceptions and section numbering.', null, 'navigation', '{}'::text[], array['codebook-navigation', 'mn-residential-code']::text[], 15, 20, 'unverified', null, 'published', 4),
  ('general-contractor-knowledge-practice', 'General Contractor Knowledge Practice Exam', 'A longer mixed practice exam across safety, codes, codebook navigation and business basics. Original questions; not an official licensing exam for any state.', null, 'general', '{}'::text[], array['osha-fall-protection', 'osha-excavation', 'osha-ladders-stairs', 'osha-general', 'osha-recordkeeping', 'codebook-navigation', 'business-setup', 'insurance-terms', 'licensing-basics', 'mn-permits', 'mn-residential-code']::text[], 50, 90, 'unverified', null, 'published', 5)
